1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID     string `json:"id"`
27		Name   string `json:"name"`
28		Price  int64  `json:"price_fen"`         // 固定单价，非负整数分，创建后不可修改
29		PlanID string `json:"plan_id,omitempty"` // 绑定的阶梯计费方案标识；空表示固定单价客户，创建后不可变更
30	}
31	
32	// tier 是阶梯计费方案中的一档：Limit 为月累计数量上限（正整数），
33	// 仅最后一档无上限（Limit 为 0）；Price 为该档每单位价格（非负整数分）。
34	type tier struct {
35		Limit int64 `json:"limit"`     // 累计数量上限；0 表示无上限（仅最后一档）
36		Price int64 `json:"price_fen"` // 每单位价格，非负整数分，可升可降
37	}
38	
39	// plan 是按月累计用量的阶梯计费方案：标识唯一非空、名称非空、固定月费
40	// （非负整数分，省略视为 0）与至少一档有序阶梯；月费与规则创建后不可修改。
41	type plan struct {
42		ID         string `json:"id"`
43		Name       string `json:"name"`
44		MonthlyFee int64  `json:"monthly_fee_fen,omitempty"` // 固定月费，非负整数分；每账期收取一次整月，不按天折算
45		Tiers      []tier `json:"tiers"`                     // 至少一档；有限上限严格递增，最后一档无上限
46	}
47	
48	type usageRecord struct {
49		ID         string `json:"id"`
50		CustomerID string `json:"customer_id"`
51		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
52		Quantity   int64  `json:"quantity"`
53	}
54	
55	// lineSegment 是阶梯计费下一条用量记录落入某一档的分段：数量与小计；
56	// 该档单价由账单保存的方案规则按档位序号取得。
57	type lineSegment struct {
58		Tier     int   `json:"tier"`     // 档位序号（0 起，对应账单保存的方案规则）
59		Quantity int64 `json:"quantity"` // 落入本档的数量
60		Fee      int64 `json:"fee_fen"`  // 本分段小计（数量 × 该档单价）
61	}
62	
63	// tierTotal 是阶梯账单中某一档的合计数量与金额（与 PlanTiers 顺序对齐）。
64	type tierTotal struct {
65		Quantity int64 `json:"quantity"`
66		Fee      int64 `json:"fee_fen"`
67	}
68	
69	type billLine struct {
70		UsageID  string        `json:"usage_id"`
71		Time     string        `json:"time"`
72		Quantity int64         `json:"quantity"`
73		LineFee  int64         `json:"line_fee_fen"`
74		Segments []lineSegment `json:"segments,omitempty"` // 阶梯账单：本条用量的跨档分段
75	}
76	
77	type bill struct {
78		ID         string      `json:"id"`
79		CustomerID string      `json:"customer_id"`
80		Month      string      `json:"month"`                 // YYYY-MM（UTC）
81		Pricing    string      `json:"pricing,omitempty"`     // 计价类型：空或 fixed 为固定单价；tiered 为阶梯计费
82		PlanID     string      `json:"plan_id,omitempty"`     // 阶梯账单：方案标识
83		PlanName   string      `json:"plan_name,omitempty"`   // 阶梯账单：方案名称（快照）
84		PlanTiers  []tier      `json:"plan_tiers,omitempty"`  // 阶梯账单：完整方案规则（快照）
85		TierTotals []tierTotal `json:"tier_totals,omitempty"` // 阶梯账单：各档实际数量与金额合计
86		// 阶梯账单：实际收取的固定月费快照（分），非负；按账期有效方案收取一次
87		// 整月，不计入总数量、各档金额或逐条小计。固定单价账单恒为 0。
88		MonthlyFee int64      `json:"monthly_fee_fen,omitempty"`
89		TotalQty   int64      `json:"total_quantity"`
90		UnitPrice  int64      `json:"unit_price_fen"` // 固定单价账单的单价；阶梯账单恒为 0（不伪造统一单价）
91		TotalFee   int64      `json:"total_fee_fen"`
92		Lines      []billLine `json:"lines"`
93		CreatedAt  string     `json:"created_at"`
94	}
95	
96	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
97	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
98	type adjustment struct {
99		ID           string `json:"id"`
100		CustomerID   string `json:"customer_id"`
101		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
102		Amount       int64  `json:"amount_fen"`
103		Reason       string `json:"reason"`
104		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
105		CreatedAt    string `json:"created_at"`
106		Revoked      bool   `json:"revoked"`
107		RevokeReason string `json:"revoke_reason,omitempty"`
108		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
109		RevokedAt    string `json:"revoked_at,omitempty"`
110	}
111	
112	// paymentAllocation 是一笔收款在某个已结算月份上的分配（正整数分）。
113	type paymentAllocation struct {
114		Month  string `json:"month"`      // YYYY-MM（UTC），须已有账单
115		Amount int64  `json:"amount_fen"` // 正整数分
116	}
117	
118	// payment 是一笔实收登记：同一客户的一笔汇款（总额 Total 分）按分配列表
119	// 计入一个或多个已结算月份；单账单收款视为只有一项分配的汇款。
120	// 记录一旦写入永不删除；撤销只是追加撤销信息，整笔撤销全部分配并保留
121	// 原记录，撤销后该笔不再计入实收，也不会因重放而恢复。
122	type payment struct {
123		ID          string              `json:"id"`
124		CustomerID  string              `json:"customer_id"`
125		Total       int64               `json:"total_fen"` // 收款总额，正整数分，等于分配合计
126		Note        string              `json:"note"`
127		Allocations []paymentAllocation `json:"allocations"` // 至少一项，月份不重复，按月份升序保存
128		// Auto 为 true 表示该收款由 bill remit-auto 自动分配登记：首次分配由工具
129		// 按最早欠款账期确定，判重只看客户、总额与备注；false（含旧存档缺字段）
130		// 表示 bill pay / bill remit 的显式分配登记，仍按月份-金额对应关系判重。
131		// 自动与显式分配登记之间不得复用同一收款标识。
132		Auto         bool   `json:"auto,omitempty"`
133		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
134		CreatedAt    string `json:"created_at"`
135		Revoked      bool   `json:"revoked"`
136		RevokeReason string `json:"revoke_reason,omitempty"`
137		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
138		RevokedAt    string `json:"revoked_at,omitempty"`
139	}
140	
141	// UnmarshalJSON 兼容旧版单账单收款格式（month + amount_fen，无 allocations）：
142	// 读入时归一化为一项分配，之后一律按新格式写回。
143	func (p *payment) UnmarshalJSON(data []byte) error {
144		type plain payment // 去掉方法，避免递归
145		var raw struct {
146			plain
147			Month  string `json:"month"`      // 旧格式：所属账单月份
148			Amount int64  `json:"amount_fen"` // 旧格式：收款金额
149		}
150		if err := json.Unmarshal(data, &raw); err != nil {
151			return err
152		}
153		*p = payment(raw.plain)
154		if len(p.Allocations) == 0 && raw.Month != "" {
155			p.Allocations = []paymentAllocation{{Month: raw.Month, Amount: raw.Amount}}
156			p.Total = raw.Amount
157		}
158		return nil
159	}
160	
161	// amountFor 返回该收款在指定月份的分配金额；无分配时为 0。
162	func (p *payment) amountFor(month string) int64 {
163		for _, al := range p.Allocations {
164			if al.Month == month {
165				return al.Amount
166			}
167		}
168		return 0
169	}
170	
171	// correction 是对一笔未撤销收款的一次更正登记，分两类：
172	//
173	//   - 分配更正（Reassign 为 false）：客户、总额、备注、原账单及应付不变，
174	//     仅把该笔收款当前生效的分配整体替换为完整新分配。记录一旦写入永不
175	//     删除；首次登记内容永久保留，bill pay / bill remit 仍按原始分配判重，
176	//     更正不影响收款身份。可连续更正，每次以当时最新分配为起点。
177	//   - 收款客户归属更正（Reassign 为 true，bill reassign）：把整笔实收从
178	//     当前归属客户转移到另一个已存在客户，不重复收钱。当前客户最新分配
179	//     整笔撤去，计入目标客户的新分配（Allocations）；原登记客户、总额、
180	//     备注、首次分配及自动或显式登记身份不改写，收款 CustomerID 仍为首次
181	//     登记客户。记录永久保留、不可撤销，可连续更正（包括再次归属更正）。
182	//
183	// 两类更正共用全局唯一更正标识：同一标识不可跨类型复用。
184	type correction struct {
185		ID          string              `json:"id"`
186		PaymentID   string              `json:"payment_id"` // 目标收款标识
187		Reason      string              `json:"reason"`
188		Allocations []paymentAllocation `json:"allocations"` // 完整新分配，至少一项，月份不重复，按月份升序保存
189		// Reassign 为 true 表示这是一笔收款客户归属更正：Allocations 的月份
190		// 属于目标客户 TargetCustomerID（异于更正发生时的当前归属客户）；
191		// false（含旧存档缺字段）表示同客户分配更正，月份属于收款当前归属客户。
192		Reassign         bool   `json:"reassign,omitempty"`
193		TargetCustomerID string `json:"target_customer_id,omitempty"` // 归属更正的目标客户标识；仅 Reassign 为 true 时非空
194		Seq              int64  `json:"seq"`                          // 全局递增操作序号，与调整/收款及其撤销共用
195		CreatedAt        string `json:"created_at"`
196	}
197	
198	// refund 是对一笔已登记收款的部分退款登记：从该收款当前最新分配涉及的
199	// 月份中实际退回资金，各月退款金额为正整数分，累计不得超过该笔在该月的
200	// 分配。记录一旦写入永不删除、不可撤销；首次退款后该收款的最新分配固定，
201	// 不得再新增分配更正或整笔撤销。退款标识与收款、调整、更正标识命名空间
202	// 相互独立，可同名。
203	type refund struct {
204		ID          string              `json:"id"`
205		PaymentID   string              `json:"payment_id"` // 目标收款标识
206		Reason      string              `json:"reason"`
207		Allocations []paymentAllocation `json:"allocations"` // 各月退款金额，至少一项，月份不重复，按月份升序保存
208		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款/更正及其撤销共用
209		CreatedAt   string              `json:"created_at"`
210	}
211	
212	// planChange 是阶梯客户的一次按月生效的方案变更：自生效月（UTC 自然月，
213	// 含）起改用目标方案，直到下一次变更；生效月之前的月份不受影响。记录一旦
214	// 写入永不修改或删除；变更不产生账后流水事件，也不占用全局操作序号。
215	// 变更可被 plan revoke 撤销：撤销只追加撤销记录（PlanChangeRevocations），
216	// 原变更内容与原原因永久保留；有效方案只考虑未撤销变更，已撤销变更的月份
217	// 槽位仍永久占用（新变更不得复用该客户月份）。
218	type planChange struct {
219		CustomerID string `json:"customer_id"`
220		Month      string `json:"month"`   // YYYY-MM（UTC），生效月（含）
221		PlanID     string `json:"plan_id"` // 目标阶梯计费方案标识
222		Reason     string `json:"reason"`
223		CreatedAt  string `json:"created_at"`
224	}
225	
226	// planChangeRevocation 是一项方案变更的撤销登记：以客户与目标变更生效月
227	// 共同识别目标变更。原变更内容（目标方案与原因）永久保留，撤销只追加本
228	// 记录；撤销记录永久保留、不可撤销，每项变更只能撤销一次。撤销不产生账后
229	// 流水事件，也不占用全局操作序号。撤销后目标变更不再参与有效方案安排：
230	// 自其生效月起沿用此前最后一项未撤销变更的方案，无则用初始方案。
231	type planChangeRevocation struct {
232		CustomerID string `json:"customer_id"`
233		Month      string `json:"month"`  // 目标变更的生效月（YYYY-MM，UTC），与客户共同标识撤销目标
234		Reason     string `json:"reason"` // 撤销原因，非空
235		CreatedAt  string `json:"created_at"`
236	}
237	
238	// suspension 是阶梯客户的一段按月暂停区间：自起月（UTC 自然月，含）起
239	// 暂停服务，直到结束月（不含），即 [StartMonth, EndMonth) 覆盖的自然月。
240	// 暂停月不接收用量、不产生月费账单；区间可相接（相接视为连续暂停）但不得
241	// 重叠。记录一旦写入永不修改或删除；暂停不产生账后流水事件，也不占用全局
242	// 操作序号。固定单价客户不适用暂停。
243	type suspension struct {
244		CustomerID string `json:"customer_id"`
245		StartMonth string `json:"start_month"` // YYYY-MM（UTC），暂停起月（含）
246		EndMonth   string `json:"end_month"`   // YYYY-MM（UTC），原结束月（不含），严格晚于起月；登记提前恢复后仍永久保留原值
247		Reason     string `json:"reason"`      // 原暂停原因，永久保留
248		CreatedAt  string `json:"created_at"`
249	}
250	
251	// suspensionResume 是一段暂停的按月提前恢复登记：目标暂停由客户与原起月
252	// 共同标识，恢复月（UTC 自然月，含）起重新提供服务，该月不再受该项暂停
253	// 限制；目标暂停的当前有效区间由 [原起月, 原结束月) 缩短为 [原起月, 恢复月)，
254	// 原区间与原原因永久保留。恢复记录一旦写入永不修改、不可撤销，每项暂停只能
255	// 登记一次提前恢复；恢复不产生账后流水事件，也不占用全局操作序号。
256	type suspensionResume struct {
257		CustomerID  string `json:"customer_id"`
258		StartMonth  string `json:"start_month"`  // 目标暂停的原起月（YYYY-MM，UTC），与客户共同标识目标暂停
259		ResumeMonth string `json:"resume_month"` // YYYY-MM（UTC），恢复月（含）；严格满足 原起月 < 恢复月 < 原结束月
260		Reason      string `json:"reason"`       // 恢复原因，非空
261		CreatedAt   string `json:"created_at"`
262	}
263	
264	// termination 是阶梯客户的按月订阅终止登记：自终止月（UTC 自然月，含）起
265	// 永久结束后续服务——不接收新用量、不结算、不封账、不收月费、不生成零金额
266	// 账单，终止前月份仍按原规则补结算，历史账务全部保留。每客户只能登记一次，
267	// 记录永久保留、不可修改或撤销，客户标识不能复用；终止不产生账后流水事件，
268	// 也不占用全局操作序号。固定单价客户不适用终止。
269	type termination struct {
270		CustomerID string `json:"customer_id"`
271		Month      string `json:"month"` // YYYY-MM（UTC），终止月（含），与操作当天无关
272		Reason     string `json:"reason"`
273		CreatedAt  string `json:"created_at"`
274	}
275	
276	// withdrawal 是一条用量记录的撤回标记：原记录（客户、时间、数量、标识）永久
277	// 保留在 Usage 中，撤回只追加状态与原因，用于纠正误导入的记录。撤回不可恢复、
278	// 标识不可复用；已撤回用量不参与结算、方案变更预检与暂停区间冲突检查，但相同
279	// 内容的重放仍按原记录判重跳过。撤回只作用于该条记录，不占用全局操作序号。
280	type withdrawal struct {
281		UsageID   string `json:"usage_id"` // 撤回的用量标识（与键一致）
282		Reason    string `json:"reason"`   // 撤回原因，非空
283		CreatedAt string `json:"created_at"`
284	}
285	
286	// usageCorrection 是一条未封账用量的原子更正：以原用量标识为键，把错误的
287	// 客户、时间或数量替换为一条全新替代记录。更正成功时原记录按更正原因登记
288	// 撤回（Withdrawals 中保存同因撤回标记），替代记录登记到 Usage 并在此永久
289	// 保存关联；原内容不可改写，更正不可撤销，不占用账后操作序号。每条原用量
290	// 只能更正一次；替代记录本身仍可继续更正（形成前身→后继链）或按原规则撤回。
291	// 字段保存首次更正请求的完整内容，用于相同请求的幂等重放判定（时间按解析后
292	// 的瞬间比较）。
293	type usageCorrection struct {
294		UsageID       string `json:"usage_id"`       // 原用量标识（与键一致）
295		ReplacementID string `json:"replacement_id"` // 替代用量标识（全局唯一，首次更正时全新）
296		NewCustomerID string `json:"new_customer_id"`
297		NewTime       string `json:"new_time"` // RFC3339，保留首次更正的原始输入
298		NewQuantity   int64  `json:"new_quantity"`
299		Reason        string `json:"reason"` // 更正原因，同时是原记录的撤回原因，非空
300		CreatedAt     string `json:"created_at"`
301	}
302	
303	type state struct {
304		Version     int                     `json:"version"`
305		Customers   map[string]*customer    `json:"customers"`
306		Plans       map[string]*plan        `json:"plans"`             // 全局唯一方案标识 -> 阶梯计费方案
307		Usage       map[string]*usageRecord `json:"usage"`             // 全局唯一用量标识 -> 记录
308		Bills       map[string]*bill        `json:"bills"`             // 客户 + "|" + 月份 -> 账单
309		Adjustments map[string]*adjustment  `json:"adjustments"`       // 全局唯一调整标识 -> 记录
310		Payments    map[string]*payment     `json:"payments"`          // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
311		Corrections map[string]*correction  `json:"corrections"`       // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
312		Refunds     map[string]*refund      `json:"refunds,omitempty"` // 全局唯一退款标识 -> 记录（与收款、调整、更正标识相互独立，可同名；不可撤销）
313		PlanChanges map[string]*planChange  `json:"plan_changes"`      // 客户 + "|" + 生效月 -> 方案变更（按生效月递增追加，不可改写；撤销后原记录仍保留）
314		// PlanChangeRevocations 以客户与目标变更生效月为键保存方案变更撤销登记；
315		// 原变更仍保留在 PlanChanges 中并永久可追溯，有效方案只考虑未撤销变更。
316		// 旧存档缺少本字段时全部变更视为有效。撤销记录永久保留、不可撤销。
317		PlanChangeRevocations map[string]*planChangeRevocation `json:"plan_change_revocations,omitempty"`
318		Suspensions           map[string]*suspension           `json:"suspensions,omitempty"` // 客户 + "|" + 起月 -> 暂停区间（原区间与原因不可改写）
319		// SuspensionResumes 以客户与原起月为键保存暂停的提前恢复登记；旧存档
320		// 缺少本字段时暂停沿用原区间。恢复记录永久保留、不可改写或撤销。
321		SuspensionResumes map[string]*suspensionResume `json:"suspension_resumes,omitempty"`
322		Withdrawals       map[string]*withdrawal       `json:"withdrawals,omitempty"` // 用量标识 -> 撤回标记（不可恢复，标识不可复用）
323		// UsageCorrections 以原用量标识为键保存用量更正关联；原记录同时在
324		// Withdrawals 中按更正原因标记撤回。旧存档缺少本字段视为无更正。
325		UsageCorrections map[string]*usageCorrection `json:"usage_corrections,omitempty"`
326		// Terminations 以客户标识为键保存按月订阅终止登记；每客户至多一条，
327		// 永久保留、不可修改或撤销。旧存档缺少本字段视为未终止。
328		Terminations map[string]*termination `json:"terminations,omitempty"`
329		NextSeq      int64                   `json:"next_seq"` // 已分配的最大操作序号（调整/收款/更正/退款及其撤销共用；方案变更、暂停、用量撤回与用量更正不占用）
330		path         string                  `json:"-"`
331	}
