333	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
334	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
335	func loadStore(dir string) (*state, error) {
336		p := filepath.Join(dir, "state.json")
337		data, err := os.ReadFile(p)
338		if err != nil {
339			if errors.Is(err, os.ErrNotExist) {
340				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
341					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
342				}
343				return newState(p), nil
344			}
345			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
346		}
347	
348		var s state
349		dec := json.NewDecoder(bytes.NewReader(data))
350		if err := dec.Decode(&s); err != nil {
351			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
352		}
353		// 拒绝完整 JSON 之后的任何非空白内容（包括单独的 ] 或 }），避免静默
354		// 吞掉异常数据；合法尾随空白仍可读取。
355		if off := dec.InputOffset(); off < int64(len(data)) {
356			if strings.TrimSpace(string(data[off:])) != "" {
357				return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
358			}
359		}
360		if err := s.validate(); err != nil {
361			return nil, fmt.Errorf("数据文件已损坏: %w", err)
362		}
363		// 旧版本数据文件没有 plans/adjustments/payments/corrections/refunds/
364		// plan_changes/suspensions/withdrawals/usage_corrections/terminations/
365		// next_seq 字段：视为零方案、零调整、零实收、零更正、零退款、零方案变更、
366		// 零暂停、零撤回、零用量更正（全部用量有效）、未终止。
367		if s.Plans == nil {
368			s.Plans = map[string]*plan{}
369		}
370		if s.Adjustments == nil {
371			s.Adjustments = map[string]*adjustment{}
372		}
373		if s.Payments == nil {
374			s.Payments = map[string]*payment{}
375		}
376		if s.Corrections == nil {
377			s.Corrections = map[string]*correction{}
378		}
379		if s.Refunds == nil {
380			s.Refunds = map[string]*refund{}
381		}
382		if s.PlanChanges == nil {
383			s.PlanChanges = map[string]*planChange{}
384		}
385		if s.PlanChangeRevocations == nil {
386			s.PlanChangeRevocations = map[string]*planChangeRevocation{}
387		}
388		if s.Suspensions == nil {
389			s.Suspensions = map[string]*suspension{}
390		}
391		if s.SuspensionResumes == nil {
392			s.SuspensionResumes = map[string]*suspensionResume{}
393		}
394		if s.Withdrawals == nil {
395			s.Withdrawals = map[string]*withdrawal{}
396		}
397		if s.UsageCorrections == nil {
398			s.UsageCorrections = map[string]*usageCorrection{}
399		}
400		if s.Terminations == nil {
401			s.Terminations = map[string]*termination{}
402		}
403		s.path = p
404		return &s, nil
405	}
406	
407	func newState(p string) *state {
408		return &state{
409			Version:               stateVersion,
410			Customers:             map[string]*customer{},
411			Plans:                 map[string]*plan{},
412			Usage:                 map[string]*usageRecord{},
413			Bills:                 map[string]*bill{},
414			Adjustments:           map[string]*adjustment{},
415			Payments:              map[string]*payment{},
416			Corrections:           map[string]*correction{},
417			Refunds:               map[string]*refund{},
418			PlanChanges:           map[string]*planChange{},
419			PlanChangeRevocations: map[string]*planChangeRevocation{},
420			Suspensions:           map[string]*suspension{},
421			SuspensionResumes:     map[string]*suspensionResume{},
422			Withdrawals:           map[string]*withdrawal{},
423			UsageCorrections:      map[string]*usageCorrection{},
424			Terminations:          map[string]*termination{},
425			path:                  p,
426		}
427	}
428	
429	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
430	func (s *state) validate() error {
431		if s.Version != stateVersion {
432			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
433		}
434		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
435			return errors.New("缺少必要的数据节")
436		}
437		for id, p := range s.Plans {
438			if p == nil {
439				return fmt.Errorf("方案 %q 的数据为空", id)
440			}
441			if p.ID != id {
442				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
443			}
444			if err := validatePlanRules(p); err != nil {
445				return err
446			}
447		}
448		for id, c := range s.Customers {
449			if c == nil {
450				return fmt.Errorf("客户 %q 的数据为空", id)
451			}
452			if c.ID != id {
453				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
454			}
455			if c.ID == "" || c.Name == "" {
456				return fmt.Errorf("客户 %q 的标识或名称为空", id)
457			}
458			if c.Price < 0 {
459				return fmt.Errorf("客户 %q 单价为负", id)
460			}
461			if c.PlanID != "" {
462				if _, ok := s.Plans[c.PlanID]; !ok {
463					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
464				}
465			}
466		}
467		// 方案变更：键、客户（须为绑定阶梯方案的客户）、目标方案、生效月与
468		// 原因都必须自洽；同一客户的变更生效月由键保证唯一。
469		for key, ch := range s.PlanChanges {
470			if ch == nil {
471				return fmt.Errorf("方案变更 %q 的数据为空", key)
472			}
473			if planChangeKey(ch.CustomerID, ch.Month) != key {
474				return fmt.Errorf("方案变更键不一致: 键 %q / 客户月份 %s|%s", key, ch.CustomerID, ch.Month)
475			}
476			c, ok := s.Customers[ch.CustomerID]
477			if !ok {
478				return fmt.Errorf("方案变更 %q 引用了不存在的客户 %q", key, ch.CustomerID)
479			}
480			if c.PlanID == "" {
481				return fmt.Errorf("方案变更 %q 的客户 %q 未绑定阶梯方案", key, ch.CustomerID)
482			}
483			if !validMonth(ch.Month) {
484				return fmt.Errorf("方案变更 %q 的生效月无效", key)
485			}
486			if _, ok := s.Plans[ch.PlanID]; !ok {
487				return fmt.Errorf("方案变更 %q 引用了不存在的方案 %q", key, ch.PlanID)
488			}
489			if strings.TrimSpace(ch.Reason) == "" {
490				return fmt.Errorf("方案变更 %q 的原因为空", key)
491			}
492		}
493		// 方案变更撤销登记：键与客户/目标生效月一致；引用的目标变更必须存在
494		// （失效撤销引用即损坏）；撤销原因非空。原变更内容、原原因与撤销记录都
495		// 永久保留，撤销不可撤销。旧文件缺少撤销记录时全部变更视为有效
496		// （PlanChangeRevocations 已在载入时补为空表）。账单方案与撤销后有效
497		// 安排的一致性由阶梯账单校验（validateTieredBill）把关。
498		for key, rv := range s.PlanChangeRevocations {
499			if rv == nil {
500				return fmt.Errorf("方案变更撤销 %q 的数据为空", key)
501			}
502			if planChangeKey(rv.CustomerID, rv.Month) != key {
503				return fmt.Errorf("方案变更撤销键不一致: 键 %q / 客户月份 %s|%s", key, rv.CustomerID, rv.Month)
504			}
505			if _, ok := s.PlanChanges[key]; !ok {
506				return fmt.Errorf("方案变更撤销 %q 引用了不存在的方案变更（客户 %q 生效月 %q，撤销目标失效）",
507					key, rv.CustomerID, rv.Month)
508			}
509			if !validMonth(rv.Month) {
510				return fmt.Errorf("方案变更撤销 %q 的目标生效月无效", key)
511			}
512			if strings.TrimSpace(rv.Reason) == "" {
513				return fmt.Errorf("方案变更撤销 %q 的原因为空", key)
514			}
515		}
516		for id, u := range s.Usage {
517			if u == nil {
518				return fmt.Errorf("用量 %q 的数据为空", id)
519			}
520			if u.ID != id {
521				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
522			}
523			if u.ID == "" {
524				return errors.New("存在空的用量标识")
525			}
526			if _, ok := s.Customers[u.CustomerID]; !ok {
527				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
528			}
529			if u.Quantity <= 0 {
530				return fmt.Errorf("用量 %q 的数量非正", u.ID)
531			}
532			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
533				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
534			}
535		}
536		// 撤回标记：键与记录一致、目标用量存在（撤回目标失效即损坏）、原因非空。
537		// 原用量记录仍按上面的规则完整校验（格式、正数量、客户存在性），撤回不
538		// 删除或改写原记录。旧文件缺少撤回记录视为全部用量有效（Withdrawals 已
539		// 在载入时补为空表）。
540		for id, w := range s.Withdrawals {
541			if w == nil {
542				return fmt.Errorf("用量 %q 的撤回记录为空", id)
543			}
544			if w.UsageID != id {
545				return fmt.Errorf("撤回记录键不一致: 键 %q / 用量标识 %q", id, w.UsageID)
546			}
547			if w.UsageID == "" {
548				return errors.New("存在空用量标识的撤回记录")
549			}
550			if _, ok := s.Usage[w.UsageID]; !ok {
551				return fmt.Errorf("撤回记录引用了不存在的用量 %q（撤回目标失效）", w.UsageID)
552			}
553			if strings.TrimSpace(w.Reason) == "" {
554				return fmt.Errorf("用量 %q 的撤回原因为空", w.UsageID)
555			}
556		}
557		// 用量更正关联：键与原标识一致；原记录与替代记录都必须存在于 Usage，
558		// 替代记录内容（客户、解析后的时间点、数量）须与更正保存的新内容一致；
559		// 原记录必须已按更正原因撤回（撤回标记的原因与更正原因不符即损坏）；
560		// 同一替代记录只能有一个来源；关联不得成环。替代记录后来被合法撤回或
561		// 继续更正（即它本身又作为某条更正的原记录）属正常状态，不判为损坏。
562		// 旧文件缺少更正记录视为无更正（UsageCorrections 已在载入时补为空表）。
563		replacementSources := make(map[string]string) // 替代用量标识 -> 原用量标识
564		for id, uc := range s.UsageCorrections {
565			if uc == nil {
566				return fmt.Errorf("用量更正 %q 的数据为空", id)
567			}
568			if uc.UsageID != id {
569				return fmt.Errorf("用量更正键不一致: 键 %q / 原用量标识 %q", id, uc.UsageID)
570			}
571			if uc.UsageID == "" {
572				return errors.New("存在空原用量标识的更正记录")
573			}
574			if strings.TrimSpace(uc.Reason) == "" {
575				return fmt.Errorf("用量更正 %q 的原因为空", id)
576			}
577			orig, ok := s.Usage[uc.UsageID]
578			if !ok {
579				return fmt.Errorf("用量更正 %q 引用了不存在的原用量 %q（更正来源失效）", id, uc.UsageID)
580			}
581			// 原记录内容不可改写：原用量记录仍须是正常的正数量有效格式（已在
582			// 上面的用量校验中核验），此处仅确认其存在。
583			if orig.ID != uc.UsageID {
584				return fmt.Errorf("用量更正 %q 的原记录标识不一致", id)
585			}
586			if uc.ReplacementID == "" {
587				return fmt.Errorf("用量更正 %q 缺少替代用量标识", id)
588			}
589			if uc.ReplacementID == uc.UsageID {
590				return fmt.Errorf("用量更正 %q 的替代标识与原标识相同", id)
591			}
592			repl, ok := s.Usage[uc.ReplacementID]
593			if !ok {
594				return fmt.Errorf("用量更正 %q 引用了不存在的替代用量 %q（更正目标失效）", id, uc.ReplacementID)
595			}
596			if src, dup := replacementSources[uc.ReplacementID]; dup {
597				return fmt.Errorf("替代用量 %q 同时是用量 %q 与 %q 的更正替代（同一替代记录不得有多个来源）",
598					uc.ReplacementID, src, uc.UsageID)
599			}
600			replacementSources[uc.ReplacementID] = uc.UsageID
601			if _, ok := s.Customers[uc.NewCustomerID]; !ok {
602				return fmt.Errorf("用量更正 %q 引用了不存在的新客户 %q", id, uc.NewCustomerID)
603			}
604			nt, err := time.Parse(time.RFC3339, uc.NewTime)
605			if err != nil {
606				return fmt.Errorf("用量更正 %q 的新时间不是 RFC3339: %w", id, err)
607			}
608			if uc.NewQuantity <= 0 {
609				return fmt.Errorf("用量更正 %q 的新数量非正", id)
610			}
611			rt, err := time.Parse(time.RFC3339, repl.Time)
612			if err != nil {
613				return fmt.Errorf("用量更正 %q 的替代记录 %q 时间不是 RFC3339: %w", id, uc.ReplacementID, err)
614			}
615			// 替代记录内容（客户、解析后的时间点、数量）必须与更正保存的新内容一致；
616			// 时间按瞬间比较，Z 与 +08:00 表示同一时刻视为一致。
617			if repl.CustomerID != uc.NewCustomerID || repl.Quantity != uc.NewQuantity || !rt.Equal(nt) {
618				return fmt.Errorf("用量更正 %q 的替代记录 %q 内容与保存的新内容不一致（更正关联损坏）",
619					id, uc.ReplacementID)
620			}
621			// 原记录必须已撤回，且撤回原因就是更正原因。
622			w, ok := s.Withdrawals[uc.UsageID]
623			if !ok {
624				return fmt.Errorf("用量更正 %q 的原用量 %q 未撤回（更正须把原记录按更正原因标记撤回）", id, uc.UsageID)
625			}
626			if w.Reason != uc.Reason {
627				return fmt.Errorf("用量更正 %q 的原用量 %q 撤回原因 %q 与更正原因 %q 不符",
628					id, uc.UsageID, w.Reason, uc.Reason)
629			}
630		}
631		// 关联成环检测：沿“原记录 -> 替代记录”的更正链前进，重复访问即成环。
632		// 合法链必然终止于一条未再被更正的记录。
633		for id := range s.UsageCorrections {
634			seen := map[string]bool{id: true}
635			cur := id
636			for {
637				uc, ok := s.UsageCorrections[cur]
638				if !ok {
639					break // 链终止于未再被更正的记录
640				}
641				if seen[uc.ReplacementID] {
642					return fmt.Errorf("用量更正关联在 %q 处成环（更正链不得成环）", uc.ReplacementID)
643				}
644				seen[uc.ReplacementID] = true
645				cur = uc.ReplacementID
646			}
647		}
648		for key, b := range s.Bills {
649			if b == nil {
650				return fmt.Errorf("账单 %q 的数据为空", key)
651			}
652			if billKey(b.CustomerID, b.Month) != key {
653				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
654			}
655			if _, ok := s.Customers[b.CustomerID]; !ok {
656				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
657			}
658			if !validMonth(b.Month) {
659				return fmt.Errorf("账单 %q 的月份无效", key)
660			}
661			if b.MonthlyFee < 0 {
662				return fmt.Errorf("账单 %q 的月费为负", key)
663			}
664			// 仅月费大于 0 的账单允许空用量明细（无用量也须出账收取月费）。
665			if len(b.Lines) == 0 && b.MonthlyFee == 0 {
666				return fmt.Errorf("账单 %q 没有明细", key)
667			}
668			var qty, fee int64
669			for _, ln := range b.Lines {
670				u, ok := s.Usage[ln.UsageID]
671				if !ok {
672					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
673				}
674				// 已撤回用量不参与结算，账单不得把已撤回记录视为待计费用量。
675				if _, withdrawn := s.Withdrawals[ln.UsageID]; withdrawn {
676					return fmt.Errorf("账单 %q 引用了已撤回的用量 %q", key, ln.UsageID)
677				}
678				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
679					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
680				}
681				if !inMonth(u.Time, b.Month) {
682					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
683				}
684				var err error
685				qty, err = add64(qty, ln.Quantity)
686				if err != nil {
687					return fmt.Errorf("账单 %q 汇总数量溢出", key)
688				}
689				fee, err = add64(fee, ln.LineFee)
690				if err != nil {
691					return fmt.Errorf("账单 %q 汇总金额溢出", key)
692				}
693			}
694			if qty != b.TotalQty {
695				return fmt.Errorf("账单 %q 总数量与明细不符", key)
696			}
697			// 原总金额 = 月费 + 全月用量费；月费不计入逐条用量小计，故明细
698			// 小计之和等于用量费（总金额 − 月费）。月费与总金额均非负，相减
699			// 不会溢出；总金额为负或小于月费时此处必然不符。
700			if usageFee := b.TotalFee - b.MonthlyFee; fee != usageFee {
701				return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费（明细小计合计 %d 分，月费 %d 分，总金额 %d 分）",
702					key, fee, b.MonthlyFee, b.TotalFee)
703			}
704			c := s.Customers[b.CustomerID]
705			switch b.Pricing {
706			case "", "fixed":
707				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
708				// 携带阶梯方案信息、分段或月费。
709				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
710					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
711				}
712				if b.MonthlyFee != 0 {
713					return fmt.Errorf("账单 %q 是固定单价账单但携带月费", key)
714				}
715				for _, ln := range b.Lines {
716					if len(ln.Segments) > 0 {
717						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
718					}
719					lf, err := mul64(ln.Quantity, c.Price)
720					if err != nil {
721						return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
722					}
723					if lf != ln.LineFee {
724						return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
725					}
726				}
727				if b.UnitPrice != c.Price {
728					return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
729				}
730			case "tiered":
731				if err := s.validateTieredBill(key, b, c); err != nil {
732					return err
733				}
734			default:
735				return fmt.Errorf("账单 %q 的计价类型 %q 未知", key, b.Pricing)
736			}
737			// 封账期内不得存在游离于账单之外的有效用量（封账后新增被禁止，
738			// 而已入账记录理应全部在明细中）；已撤回用量不计费用，允许存在
739			// 于已封账月份而不进入账单。
740			for _, u := range s.Usage {
741				if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
742					continue
743				}
744				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
745					found := false
746					for _, ln := range b.Lines {
747						if ln.UsageID == u.ID {
748							found = true
749							break
750						}
751					}
752					if !found {
753						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
754					}
755				}
756			}
757		}
758	
759		// 暂停区间：键、客户（须为绑定阶梯方案的客户）、区间与原因都必须自洽；
760		// 同一客户的当前有效区间不得重叠（可以相接）；有效暂停月内不得存在有效
761		// （未撤回）用量或账单。登记提前恢复后原区间与原因仍永久保留，仅当前
762		// 有效区间缩短为 [原起月, 恢复月)。
763		// 旧文件缺少暂停记录视为正常服务（Suspensions 已在载入时补为空表）。
764		for key, su := range s.Suspensions {
765			if su == nil {
766				return fmt.Errorf("暂停区间 %q 的数据为空", key)
767			}
768			if suspensionKey(su.CustomerID, su.StartMonth) != key {
769				return fmt.Errorf("暂停区间键不一致: 键 %q / 客户起月 %s|%s", key, su.CustomerID, su.StartMonth)
770			}
771			c, ok := s.Customers[su.CustomerID]
772			if !ok {
773				return fmt.Errorf("暂停区间 %q 引用了不存在的客户 %q", key, su.CustomerID)
774			}
775			if c.PlanID == "" {
776				return fmt.Errorf("暂停区间 %q 的客户 %q 未绑定阶梯方案（固定单价客户不适用暂停）", key, su.CustomerID)
777			}
778			if !validMonth(su.StartMonth) {
779				return fmt.Errorf("暂停区间 %q 的起月无效", key)
780			}
781			if !validMonth(su.EndMonth) || su.EndMonth <= su.StartMonth {
782				return fmt.Errorf("暂停区间 %q 的结束月无效（结束月必须是晚于起月 %s 的 YYYY-MM）", key, su.StartMonth)
783			}
784			if strings.TrimSpace(su.Reason) == "" {
785				return fmt.Errorf("暂停区间 %q 的原因为空", key)
786			}
787		}
788		// 暂停提前恢复记录：键与客户/原起月一致；引用的目标暂停必须存在（恢复
789		// 引用缺失即损坏）；恢复月必须是严格介于原起月与原结束月之间的 YYYY-MM；
790		// 原因非空。原区间、原原因与恢复记录都永久保留，不可改写或撤销。旧文件
791		// 缺少恢复记录时暂停沿用原区间（SuspensionResumes 已在载入时补为空表）。
792		for key, r := range s.SuspensionResumes {
793			if r == nil {
794				return fmt.Errorf("暂停提前恢复 %q 的数据为空", key)
795			}
796			if suspensionKey(r.CustomerID, r.StartMonth) != key {
797				return fmt.Errorf("暂停提前恢复键不一致: 键 %q / 客户原起月 %s|%s", key, r.CustomerID, r.StartMonth)
798			}
799			su, ok := s.Suspensions[key]
800			if !ok {
801				return fmt.Errorf("暂停提前恢复 %q 引用了不存在的暂停（客户 %q 原起月 %q，恢复目标缺失）", key, r.CustomerID, r.StartMonth)
802			}
803			if !validMonth(r.ResumeMonth) {
804				return fmt.Errorf("暂停提前恢复 %q 的恢复月无效（必须是 YYYY-MM）", key)
805			}
806			if r.ResumeMonth <= su.StartMonth || r.ResumeMonth >= su.EndMonth {
807				return fmt.Errorf("暂停提前恢复 %q 的恢复月 %s 越界（必须严格满足 原起月 %s < 恢复月 < 原结束月 %s）",
808					key, r.ResumeMonth, su.StartMonth, su.EndMonth)
809			}
810			if strings.TrimSpace(r.Reason) == "" {
811				return fmt.Errorf("暂停提前恢复 %q 的原因为空", key)
812			}
813		}
814		for customerID := range s.Customers {
815			list := s.suspensionsFor(customerID)
816			for i := 1; i < len(list); i++ {
817				// 区间重叠按当前有效区间判断：提前恢复只缩短目标区间，其他暂停
818				// 独立生效；区间仍可相接（相接视为连续暂停）。
819				if list[i].StartMonth < s.suspensionEffectiveEnd(list[i-1]) {
820					return fmt.Errorf("客户 %s 的暂停有效区间 %s..%s 与 %s..%s 重叠（区间可以相接但不得重叠）",
821						customerID,
822						list[i-1].StartMonth, s.suspensionEffectiveEnd(list[i-1]),
823						list[i].StartMonth, s.suspensionEffectiveEnd(list[i]))
824				}
825			}
826			for _, su := range list {
827				// 有效暂停月为 [原起月, 当前有效结束月)：提前恢复释放的月份正常
828				// 服务，允许存在用量与账单。
829				effEnd := s.suspensionEffectiveEnd(su)
830				for _, u := range s.Usage {
831					// 已撤回用量不参与用量冲突判断，可存在于随后暂停的月份。
832					if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
833						continue
834					}
835					if u.CustomerID == customerID && monthInRange(utcMonth(u.Time), su.StartMonth, effEnd) {
836						return fmt.Errorf("客户 %s 在暂停有效区间 %s..%s（不含结束月）内存在用量 %q（%s）",
837							customerID, su.StartMonth, effEnd, u.ID, utcMonth(u.Time))
838					}
839				}
840				for _, b := range s.Bills {
841					if b.CustomerID == customerID && monthInRange(b.Month, su.StartMonth, effEnd) {
842						return fmt.Errorf("客户 %s 在暂停有效区间 %s..%s（不含结束月）内存在账单（月份 %s），暂停月不得封账",
843							customerID, su.StartMonth, effEnd, b.Month)
844					}
845				}
846			}
847		}
848	
849		// 按月订阅终止登记：键即客户标识；客户必须存在且为绑定阶梯方案的客户
850		// （固定单价客户不适用终止）；终止月必须是合法的 YYYY-MM；原因非空。
851		// 终止月（含）起不得存在有效（未撤回）用量或账单——已撤回用量与保留的
852		// 方案变更、暂停及提前恢复安排正常读取，不参与本检查。旧文件缺少终止
853		// 记录视为未终止（Terminations 已在载入时补为空表）。
854		for key, tm := range s.Terminations {
855			if tm == nil {
856				return fmt.Errorf("订阅终止 %q 的数据为空", key)
857			}
858			if tm.CustomerID != key {
859				return fmt.Errorf("订阅终止键不一致: 键 %q / 客户 %q", key, tm.CustomerID)
860			}
861			c, ok := s.Customers[tm.CustomerID]
862			if !ok {
863				return fmt.Errorf("订阅终止 %q 引用了不存在的客户 %q", key, tm.CustomerID)
864			}
865			if c.PlanID == "" {
866				return fmt.Errorf("订阅终止 %q 的客户 %q 未绑定阶梯方案（固定单价客户不适用终止）", key, tm.CustomerID)
867			}
868			if !validMonth(tm.Month) {
869				return fmt.Errorf("订阅终止 %q 的终止月无效（必须是 YYYY-MM）", key)
870			}
871			if strings.TrimSpace(tm.Reason) == "" {
872				return fmt.Errorf("订阅终止 %q 的原因为空", key)
873			}
874			for _, u := range s.Usage {
875				if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
876					continue
877				}
878				if u.CustomerID == tm.CustomerID && utcMonth(u.Time) >= tm.Month {
879					return fmt.Errorf("客户 %s 的终止月 %s 及之后存在有效用量 %q（%s），终止月起不接收新用量",
880						tm.CustomerID, tm.Month, u.ID, utcMonth(u.Time))
881				}
882			}
883			for _, b := range s.Bills {
884				if b.CustomerID == tm.CustomerID && b.Month >= tm.Month {
885					return fmt.Errorf("客户 %s 的终止月 %s 及之后存在账单（月份 %s），终止月起不结算、不封账",
886						tm.CustomerID, tm.Month, b.Month)
887				}
888			}
889		}
890	
891		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
892		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
893		// 允许同名，各自判重与撤销。
894		if s.NextSeq < 0 {
895			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
896		}
897		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
898		for id, a := range s.Adjustments {
899			if a == nil {
900				return fmt.Errorf("调整 %q 的数据为空", id)
901			}
902			if a.ID != id {
903				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
904			}
905			if a.ID == "" {
906				return errors.New("存在空的调整标识")
907			}
908			if a.Amount == 0 {
909				return fmt.Errorf("调整 %q 的金额为零", id)
910			}
911			if strings.TrimSpace(a.Reason) == "" {
912				return fmt.Errorf("调整 %q 的原因为空", id)
913			}
914			if !validMonth(a.Month) {
915				return fmt.Errorf("调整 %q 的月份无效", id)
916			}
917			if _, ok := s.Customers[a.CustomerID]; !ok {
918				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
919			}
920			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
921				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
922			}
923			if a.Seq < 1 || a.Seq > s.NextSeq {
924				return fmt.Errorf("调整 %q 的操作序号越界", id)
925			}
926			if prev, dup := seenSeq[a.Seq]; dup {
927				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
928			}
929			seenSeq[a.Seq] = "调整 " + id
930			if a.Revoked {
931				if strings.TrimSpace(a.RevokeReason) == "" {
932					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
933				}
934				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
935					return fmt.Errorf("调整 %q 的撤销序号越界", id)
936				}
937				if prev, dup := seenSeq[a.RevokeSeq]; dup {
938					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
939				}
940				seenSeq[a.RevokeSeq] = "撤销调整 " + id
941			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
942				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
943			}
944		}
945		for id, p := range s.Payments {
946			if p == nil {
947				return fmt.Errorf("收款 %q 的数据为空", id)
948			}
949			if p.ID != id {
950				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
951			}
952			if p.ID == "" {
953				return errors.New("存在空的收款标识")
954			}
955			if p.Total <= 0 {
956				return fmt.Errorf("收款 %q 的总额不是正整数", id)
957			}
958			if strings.TrimSpace(p.Note) == "" {
959				return fmt.Errorf("收款 %q 的备注为空", id)
960			}
961			if _, ok := s.Customers[p.CustomerID]; !ok {
962				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
963			}
964			if len(p.Allocations) == 0 {
965				return fmt.Errorf("收款 %q 没有分配", id)
966			}
967			seenMonths := make(map[string]bool)
968			var sum int64
969			for _, al := range p.Allocations {
970				if !validMonth(al.Month) {
971					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
972				}
973				if seenMonths[al.Month] {
974					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
975				}
976				seenMonths[al.Month] = true
977				if al.Amount <= 0 {
978					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
979				}
980				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
981					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
982				}
983				var err error
984				sum, err = add64(sum, al.Amount)
985				if err != nil {
986					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
987				}
988			}
989			if sum != p.Total {
990				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
991			}
992			if p.Seq < 1 || p.Seq > s.NextSeq {
993				return fmt.Errorf("收款 %q 的操作序号越界", id)
994			}
995			if prev, dup := seenSeq[p.Seq]; dup {
996				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
997			}
998			seenSeq[p.Seq] = "收款 " + id
999			if p.Revoked {
1000				if strings.TrimSpace(p.RevokeReason) == "" {
1001					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
1002				}
1003				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
1004					return fmt.Errorf("收款 %q 的撤销序号越界", id)
1005				}
1006				if prev, dup := seenSeq[p.RevokeSeq]; dup {
1007					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
1008				}
1009				seenSeq[p.RevokeSeq] = "撤销收款 " + id
1010			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
1011				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
1012			}
1013		}
1014		// 分配更正与归属更正记录：标识、目标收款、原因、新分配与序号都必须自洽。
1015		// 两类更正共用全局唯一更正标识（map 键保证），不可跨类型复用；允许与收款、
1016		// 调整标识同名。分配更正的月份须属于更正发生时（序号前一状态）当前归属
1017		// 客户的已存在账单；归属更正的目标客户须存在且异于当前归属客户，月份须
1018		// 属于目标客户的已存在账单。归属时间线与逐步余额在本循环之后统一回放核验。
1019		for id, c := range s.Corrections {
1020			if c == nil {
1021				return fmt.Errorf("更正 %q 的数据为空", id)
1022			}
1023			if c.ID != id {
1024				return fmt.Errorf("更正标识不一致: 键 %q / 记录 %q", id, c.ID)
1025			}
1026			if c.ID == "" {
1027				return errors.New("存在空的更正标识")
1028			}
1029			p, ok := s.Payments[c.PaymentID]
1030			if !ok {
1031				return fmt.Errorf("更正 %q 引用了不存在的收款 %q", id, c.PaymentID)
1032			}
1033			if strings.TrimSpace(c.Reason) == "" {
1034				return fmt.Errorf("更正 %q 的原因为空", id)
1035			}
1036			if len(c.Allocations) == 0 {
1037				return fmt.Errorf("更正 %q 没有新分配", id)
1038			}
1039			// 归属更正必须带目标客户；分配更正不得带目标客户。
1040			if c.Reassign {
1041				if c.TargetCustomerID == "" {
1042					return fmt.Errorf("归属更正 %q 缺少目标客户", id)
1043				}
1044				if _, ok := s.Customers[c.TargetCustomerID]; !ok {
1045					return fmt.Errorf("归属更正 %q 引用了不存在的目标客户 %q", id, c.TargetCustomerID)
1046				}
1047			} else if c.TargetCustomerID != "" {
1048				return fmt.Errorf("分配更正 %q 携带了目标客户 %q（仅归属更正允许转移客户）", id, c.TargetCustomerID)
1049			}
1050			// 更正发生时（序号前一状态）收款的归属客户；归属更正的目标必须异于
1051			// 该客户，分配月份按更正类型归属到对应客户的已存在账单。
1052			ownerBefore := paymentOwnerAt(s, p, c.Seq-1)
1053			allocCustomer := ownerBefore
1054			if c.Reassign {
1055				if c.TargetCustomerID == ownerBefore {
1056					return fmt.Errorf("归属更正 %q 的目标客户 %q 与收款 %q 当前归属客户相同，不得自我归属更正", id, c.TargetCustomerID, c.PaymentID)
1057				}
1058				allocCustomer = c.TargetCustomerID
1059			}
1060			seenMonths := make(map[string]bool)
1061			var sum int64
1062			for _, al := range c.Allocations {
1063				if !validMonth(al.Month) {
1064					return fmt.Errorf("更正 %q 的分配月份 %q 无效", id, al.Month)
1065				}
1066				if seenMonths[al.Month] {
1067					return fmt.Errorf("更正 %q 的分配月份 %s 重复", id, al.Month)
1068				}
1069				seenMonths[al.Month] = true
1070				if al.Amount <= 0 {
1071					return fmt.Errorf("更正 %q 在 %s 的分配金额不是正整数", id, al.Month)
1072				}
1073				if _, ok := s.Bills[billKey(allocCustomer, al.Month)]; !ok {
1074					return fmt.Errorf("更正 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, allocCustomer, al.Month)
1075				}
1076				var err error
1077				sum, err = add64(sum, al.Amount)
1078				if err != nil {
1079					return fmt.Errorf("更正 %q 的分配金额汇总溢出: %w", id, err)
1080				}
1081			}
1082			if sum != p.Total {
1083				return fmt.Errorf("更正 %q 的分配合计 %d 分与关联收款 %q 的总额 %d 分不一致", id, sum, c.PaymentID, p.Total)
1084			}
1085			if c.Seq <= p.Seq || c.Seq > s.NextSeq {
1086				return fmt.Errorf("更正 %q 的操作序号越界", id)
1087			}
1088			if p.Revoked && c.Seq > p.RevokeSeq {
1089				return fmt.Errorf("更正 %q 的操作序号晚于关联收款 %q 的撤销序号", id, c.PaymentID)
1090			}
1091			if prev, dup := seenSeq[c.Seq]; dup {
1092				return fmt.Errorf("更正 %q 与 %q 的操作序号重复", id, prev)
1093			}
1094			seenSeq[c.Seq] = "更正 " + id
1095		}
1096		// 退款记录：标识、目标收款、原因、各月退款与序号都必须自洽。退款标识与
1097		// 收款、调整、更正标识命名空间相互独立，允许同名。退款只作用于未撤销
1098		// 收款的最新分配涉及的月份；首次退款后该收款不得再更正或整笔撤销，
1099		// 因此全部退款都以当前最新分配为准核验，累计不得超退。旧文件缺少退款
1100		// 记录视为无退款（Refunds 已在载入时补为空表）。
1101		for id, r := range s.Refunds {
1102			if r == nil {
1103				return fmt.Errorf("退款 %q 的数据为空", id)
1104			}
1105			if r.ID != id {
1106				return fmt.Errorf("退款标识不一致: 键 %q / 记录 %q", id, r.ID)
1107			}
1108			if r.ID == "" {
1109				return errors.New("存在空的退款标识")
1110			}
1111			p, ok := s.Payments[r.PaymentID]
1112			if !ok {
1113				return fmt.Errorf("退款 %q 引用了不存在的收款 %q（退款目标失效）", id, r.PaymentID)
1114			}
1115			if strings.TrimSpace(r.Reason) == "" {
1116				return fmt.Errorf("退款 %q 的原因为空", id)
1117			}
1118			if len(r.Allocations) == 0 {
1119				return fmt.Errorf("退款 %q 没有月份金额清单", id)
1120			}
1121			current := currentAllocations(s, p)
1122			seenMonths := make(map[string]bool)
1123			for _, al := range r.Allocations {
1124				if !validMonth(al.Month) {
1125					return fmt.Errorf("退款 %q 的月份 %q 无效", id, al.Month)
1126				}
1127				if seenMonths[al.Month] {
1128					return fmt.Errorf("退款 %q 的月份 %s 重复", id, al.Month)
1129				}
1130				seenMonths[al.Month] = true
1131				if al.Amount <= 0 {
1132					return fmt.Errorf("退款 %q 在 %s 的金额不是正整数", id, al.Month)
1133				}
1134				if allocAmountFor(current, al.Month) <= 0 {
1135					return fmt.Errorf("退款 %q 的月份 %s 不在收款 %q 的最新分配中（仅允许退最新分配涉及的月份）", id, al.Month, r.PaymentID)
1136				}
1137			}
1138			if r.Seq <= p.Seq || r.Seq > s.NextSeq {
1139				return fmt.Errorf("退款 %q 的操作序号越界", id)
1140			}
1141			if prev, dup := seenSeq[r.Seq]; dup {
1142				return fmt.Errorf("退款 %q 与 %q 的操作序号重复", id, prev)
1143			}
1144			seenSeq[r.Seq] = "退款 " + id
1145		}
1146		// 逐收款核验退款相关约束：已退款的收款不得被整笔撤销；首次退款后不得
1147		// 再出现任何更正（分配更正与归属更正都禁止，最新分配已固定）；各月累计
1148		// 退款不得超过该笔在该月的最新分配（累计超退即余额异常）。
1149		for pid, p := range s.Payments {
1150			refs := refundsFor(s, pid)
1151			if len(refs) == 0 {
1152				continue
1153			}
1154			firstRefundSeq := refs[0].Seq // refundsFor 按序号升序
1155			if p.Revoked {
1156				return fmt.Errorf("收款 %q 已发生退款（首次退款序号 %d）却又被整笔撤销（序号 %d），操作先后非法", pid, firstRefundSeq, p.RevokeSeq)
1157			}
1158			for _, c := range s.Corrections {
1159				if c.PaymentID == pid && c.Seq > firstRefundSeq {
1160					kind := "分配更正"
1161					if c.Reassign {
1162						kind = "归属更正"
1163					}
1164					return fmt.Errorf("%s %q 的序号 %d 晚于收款 %q 的首次退款序号 %d（首次退款后最新分配已固定，两类更正均禁止新增），操作先后非法",
1165						kind, c.ID, c.Seq, pid, firstRefundSeq)
1166				}
1167			}
1168			current := currentAllocations(s, p)
1169			totals := make(map[string]int64)
1170			for _, r := range refs {
1171				for _, al := range r.Allocations {
1172					sum, err := add64(totals[al.Month], al.Amount)
1173					if err != nil {
1174						return fmt.Errorf("收款 %q 在 %s 的累计退款溢出有符号 64 位整数范围，余额异常", pid, al.Month)
1175					}
1176					totals[al.Month] = sum
1177				}
1178			}
1179			for month, refunded := range totals {
1180				if alloc := allocAmountFor(current, month); refunded > alloc {
1181					return fmt.Errorf("收款 %q 在 %s 的累计退款 %d 分超过该月分配 %d 分（累计超退），余额异常", pid, month, refunded, alloc)
1182				}
1183			}
1184		}
1185		// 逐步回放全部账后操作，核验每张被触及账单在每一步之后都满足
1186		// 0 ≤ 实收 ≤ 应付 ≤ 有符号 64 位最大值——归属更正把实收从原客户账单整笔
1187		// 转出、计入目标客户账单，两侧都必须在迁移发生序号即合法；只核验最终余额
1188		// 会放过中间越界的存档。截止后的迁移不提前影响历史余额也在此体现：每个
1189		// 序号只回放该序号以前（含）的操作。
1190		if err := s.validatePostbillTimeline(); err != nil {
1191			return err
1192		}
1193		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
1194		// 0 与有符号 64 位最大值之间；实收（当前归属本客户的全部未撤销收款按
1195		// 最新分配在该月计入并扣除退款后的合计）必须满足 0 ≤ 实收 ≤ 当前应付。
1196		// 越界说明金额与记录不一致。
1197		for key, b := range s.Bills {
1198			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
1199			if err != nil {
1200				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
1201			}
1202			received, err := paymentReceived(s, b.CustomerID, b.Month)
1203			if err != nil {
1204				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
1205			}
1206			if received > payable {
1207				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
1208			}
1209		}
1210		return nil
1211	}
