1213	// tvDelta 是一次账后操作对一张账单的应付/实收增量（分，带符号）。
1214	type tvDelta struct {
1215		payable  int64
1216		received int64
1217	}
1218	
1219	// validatePostbillTimeline 按全局操作序号逐步回放全部账后操作（调整及其撤销、
1220	// 收款登记、两类更正、收款撤销与退款），核验每张被触及账单在每一步之后都
1221	// 满足 0 ≤ 实收 ≤ 应付 ≤ 有符号 64 位最大值。归属更正在其发生序号把实收
1222	// 从原归属客户账单整笔转出（负增量）并计入目标客户账单（正增量），两侧在
1223	// 同一序号都必须合法；截止后的迁移因此不会提前影响较早序号的余额。任一
1224	// 中间步骤越界、溢出或回放终态与当前推导不一致，都按数据损坏拒绝。
1225	func (s *state) validatePostbillTimeline() error {
1226		type tvEvent struct {
1227			seq    int64
1228			desc   string
1229			deltas map[string]tvDelta // billKey -> 增量
1230		}
1231		var events []tvEvent
1232		addDelta := func(ev *tvEvent, key string, dpay, drecv int64) error {
1233			cur := ev.deltas[key]
1234			if dpay != 0 {
1235				v, err := addSigned64(cur.payable, dpay)
1236				if err != nil {
1237					return fmt.Errorf("操作序号 %d（%s）之后应付越出有符号 64 位整数范围，余额异常", ev.seq, ev.desc)
1238				}
1239				cur.payable = v
1240			}
1241			if drecv != 0 {
1242				v, err := addSigned64(cur.received, drecv)
1243				if err != nil {
1244					return fmt.Errorf("操作序号 %d（%s）之后实收越出有符号 64 位整数范围，余额异常", ev.seq, ev.desc)
1245				}
1246				cur.received = v
1247			}
1248			ev.deltas[key] = cur
1249			return nil
1250		}
1251	
1252		// 调整及其撤销只改所属账期应付。
1253		for _, a := range s.Adjustments {
1254			ev := tvEvent{seq: a.Seq, desc: "调整 " + a.ID, deltas: map[string]tvDelta{}}
1255			if err := addDelta(&ev, billKey(a.CustomerID, a.Month), a.Amount, 0); err != nil {
1256				return err
1257			}
1258			events = append(events, ev)
1259			if a.Revoked {
1260				neg, err := neg64(a.Amount)
1261				if err != nil {
1262					return fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），余额异常", a.ID, a.Amount)
1263				}
1264				rev := tvEvent{seq: a.RevokeSeq, desc: "撤销调整 " + a.ID, deltas: map[string]tvDelta{}}
1265				if err := addDelta(&rev, billKey(a.CustomerID, a.Month), neg, 0); err != nil {
1266					return err
1267				}
1268				events = append(events, rev)
1269			}
1270		}
1271	
1272		for _, p := range s.Payments {
1273			// 收款登记：按首次登记客户与首次分配增加对应账期实收。
1274			reg := tvEvent{seq: p.Seq, desc: "收款 " + p.ID, deltas: map[string]tvDelta{}}
1275			for _, al := range p.Allocations {
1276				if err := addDelta(&reg, billKey(p.CustomerID, al.Month), 0, al.Amount); err != nil {
1277					return err
1278				}
1279			}
1280			events = append(events, reg)
1281	
1282			// 沿更正链回放：分配更正只在同客户账单间替换；归属更正在同一序号
1283			// 从原归属客户账单整笔转出、计入目标客户账单。
1284			owner := p.CustomerID
1285			running := p.Allocations
1286			for _, c := range correctionsFor(s, p.ID) {
1287				ev := tvEvent{seq: c.Seq, deltas: map[string]tvDelta{}}
1288				if c.Reassign {
1289					ev.desc = "归属更正 " + c.ID
1290				} else {
1291					ev.desc = "更正 " + c.ID
1292				}
1293				for _, m := range unionMonths(running, c.Allocations) {
1294					oldAmt, newAmt := allocAmountFor(running, m), allocAmountFor(c.Allocations, m)
1295					if oldAmt > 0 {
1296						if err := addDelta(&ev, billKey(owner, m), 0, -oldAmt); err != nil {
1297							return err
1298						}
1299					}
1300					if newAmt > 0 {
1301						target := owner
1302						if c.Reassign {
1303							target = c.TargetCustomerID
1304						}
1305						if err := addDelta(&ev, billKey(target, m), 0, newAmt); err != nil {
1306							return err
1307						}
1308					}
1309				}
1310				events = append(events, ev)
1311				if c.Reassign {
1312					owner = c.TargetCustomerID
1313				}
1314				running = c.Allocations
1315			}
1316	
1317			// 整笔撤销取消撤销发生时最新归属客户的最新分配。
1318			if p.Revoked {
1319				rev := tvEvent{seq: p.RevokeSeq, desc: "撤销收款 " + p.ID, deltas: map[string]tvDelta{}}
1320				for _, al := range running {
1321					if err := addDelta(&rev, billKey(owner, al.Month), 0, -al.Amount); err != nil {
1322						return err
1323					}
1324				}
1325				events = append(events, rev)
1326			}
1327	
1328			// 退款只减少退款发生时归属客户的对应月实收。
1329			for _, r := range refundsFor(s, p.ID) {
1330				ownerAt := paymentOwnerAt(s, p, r.Seq)
1331				ev := tvEvent{seq: r.Seq, desc: "退款 " + r.ID, deltas: map[string]tvDelta{}}
1332				for _, al := range r.Allocations {
1333					if err := addDelta(&ev, billKey(ownerAt, al.Month), 0, -al.Amount); err != nil {
1334						return err
1335					}
1336				}
1337				events = append(events, ev)
1338			}
1339		}
1340	
1341		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
1342	
1343		payable := make(map[string]int64, len(s.Bills))
1344		received := make(map[string]int64, len(s.Bills))
1345		for key, b := range s.Bills {
1346			payable[key] = b.TotalFee
1347			received[key] = 0
1348		}
1349		for _, ev := range events {
1350			// 同一事件先累加应付再累加实收，并在每张被触及账单上校验边界。
1351			for key, d := range ev.deltas {
1352				if _, ok := payable[key]; !ok {
1353					return fmt.Errorf("操作序号 %d（%s）引用了不存在的账单 %s（引用缺失）", ev.seq, ev.desc, key)
1354				}
1355				if d.payable != 0 {
1356					v, err := addSigned64(payable[key], d.payable)
1357					if err != nil {
1358						return fmt.Errorf("操作序号 %d（%s）之后应付越出有符号 64 位整数范围，余额异常", ev.seq, ev.desc)
1359					}
1360					payable[key] = v
1361				}
1362			}
1363			for key, d := range ev.deltas {
1364				if d.received != 0 {
1365					v, err := addSigned64(received[key], d.received)
1366					if err != nil {
1367						return fmt.Errorf("操作序号 %d（%s）之后实收越出有符号 64 位整数范围，余额异常", ev.seq, ev.desc)
1368					}
1369					received[key] = v
1370				}
1371				if payable[key] < 0 {
1372					return fmt.Errorf("操作序号 %d（%s）之后账单 %s 应付为 %d 分（小于 0），逐步余额越界", ev.seq, ev.desc, key, payable[key])
1373				}
1374				if received[key] < 0 {
1375					return fmt.Errorf("操作序号 %d（%s）之后账单 %s 实收为 %d 分（小于 0），逐步余额越界", ev.seq, ev.desc, key, received[key])
1376				}
1377				if received[key] > payable[key] {
1378					return fmt.Errorf("操作序号 %d（%s）之后账单 %s 实收 %d 分超过应付 %d 分，逐步余额越界",
1379						ev.seq, ev.desc, key, received[key], payable[key])
1380				}
1381			}
1382		}
1383	
1384		// 回放终态必须与当前推导一致，确保两套计算口径相同。
1385		for key, b := range s.Bills {
1386			_, wantPayable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
1387			if err != nil {
1388				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
1389			}
1390			wantReceived, err := paymentReceived(s, b.CustomerID, b.Month)
1391			if err != nil {
1392				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
1393			}
1394			if payable[key] != wantPayable || received[key] != wantReceived {
1395				return fmt.Errorf("账单 %q 的账后回放终态（应付 %d、实收 %d）与当前余额（应付 %d、实收 %d）不一致，数据异常",
1396					key, payable[key], received[key], wantPayable, wantReceived)
1397			}
1398		}
1399		return nil
1400	}
