1450	// segmentsEqual 判定两份分段列表完全相同。
1451	func segmentsEqual(a, b []lineSegment) bool {
1452		if len(a) != len(b) {
1453			return false
1454		}
1455		for i := range a {
1456			if a[i] != b[i] {
1457				return false
1458			}
1459		}
1460		return true
1461	}
