1463	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
1464	// 标识字典序）排列，即阶梯计价的计价顺序。
1465	func sortedByInstant(recs []*usageRecord) bool {
1466		for i := 1; i < len(recs); i++ {
1467			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
1468			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
1469			ui, uj := ti.UTC(), tj.UTC()
1470			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
1471				return false
1472			}
1473		}
1474		return true
1475	}
