1477	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
1478	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
1479	// 小计、各档合计与总金额；任何不符都视为数据损坏。
1480	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
1481		if b.PlanID == "" {
1482			return fmt.Errorf("账单 %q 缺少方案标识", key)
1483		}
1484		p, ok := s.Plans[b.PlanID]
1485		if !ok {
1486			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
1487		}
1488		if b.PlanName != p.Name {
1489			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
1490		}
1491		if !tiersEqual(b.PlanTiers, p.Tiers) {
1492			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
1493		}
1494		if b.MonthlyFee != p.MonthlyFee {
1495			return fmt.Errorf("账单 %q 的月费快照与方案 %q 不符", key, b.PlanID)
1496		}
1497		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
1498		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
1499		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
1500			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
1501		}
1502		if b.UnitPrice != 0 {
1503			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
1504		}
1505		if len(b.TierTotals) != len(p.Tiers) {
1506			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
1507		}
1508		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
1509		recs := make([]*usageRecord, len(b.Lines))
1510		for i, ln := range b.Lines {
1511			recs[i] = s.Usage[ln.UsageID]
1512		}
1513		if !sortedByInstant(recs) {
1514			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
1515		}
1516		priced, err := tieredPrice(p.Tiers, recs)
1517		if err != nil {
1518			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
1519		}
1520		for i, ln := range b.Lines {
1521			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
1522				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
1523			}
1524			if ln.LineFee != priced.lines[i].fee {
1525				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
1526			}
1527		}
1528		for i, tt := range b.TierTotals {
1529			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
1530				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
1531			}
1532		}
1533		// 原总金额 = 月费 + 全月用量费；月费不进入分档合计与逐条小计。
1534		wantTotal, err := add64(priced.totalFee, b.MonthlyFee)
1535		if err != nil || wantTotal != b.TotalFee {
1536			return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费", key)
1537		}
1538		return nil
1539	}
