1694	// effectivePlanID 返回客户在某 UTC 自然月实际适用的阶梯方案标识：
1695	// 创建时绑定的初始方案，被生效月不晚于该月的最后一次**未撤销**变更替换；
1696	// 已撤销变更不参与安排——其生效月起沿用此前最后一项未撤销变更的方案，无
1697	// 则用初始方案，直到其后下一项未撤销变更的生效月前。
1698	func (s *state) effectivePlanID(cust *customer, month string) string {
1699		planID := cust.PlanID
1700		latest := ""
1701		for _, ch := range s.PlanChanges {
1702			if ch.CustomerID != cust.ID || s.planChangeRevoked(ch.CustomerID, ch.Month) {
1703				continue
1704			}
1705			if ch.Month <= month && ch.Month >= latest {
1706				latest = ch.Month
1707				planID = ch.PlanID
1708			}
1709		}
1710		return planID
1711	}
