1750	// paymentOwnerAt 返回某收款在指定操作序号完成后的归属客户标识：以首次登记
1751	// 客户为起点，按序号回放全部归属更正（Reassign），序号不晚于 at 的归属更正
1752	// 生效。分配更正不改变归属。载入时已校验归属更正目标客户存在且互不相同。
1753	func paymentOwnerAt(s *state, p *payment, at int64) string {
1754		owner := p.CustomerID
1755		for _, c := range correctionsFor(s, p.ID) {
1756			if c.Reassign && c.Seq <= at {
1757				owner = c.TargetCustomerID
1758			}
1759		}
1760		return owner
1761	}
