1770	// 客户的新分配），取序号不晚于 at 的最后一次更正结果。
1771	func allocationsAt(s *state, p *payment, at int64) []paymentAllocation {
1772		current := p.Allocations
1773		for _, c := range correctionsFor(s, p.ID) {
1774			if c.Seq <= at {
1775				current = c.Allocations
1776			}
1777		}
