1810	// paymentsEverFor 返回历史上曾以某客户为归属、且分配曾涉及该客户某月账单的
1811	// 全部收款（首次登记分配或任一次更正——含归属更正转入——涉及该月，即使后来
1812	// 被更正移出或整笔转出到其他客户），按操作序号升序。收款的首次登记客户
1813	// 永久保留在 payment.CustomerID，归属经归属更正变化，故不能只按该字段过滤。
1814	func paymentsEverFor(s *state, customerID, month string) []*payment {
1815		var list []*payment
1816		for _, p := range s.Payments {
1817			// 该收款是否曾归属于该客户：首次登记客户或某次归属更正的目标客户。
1818			everOwned := p.CustomerID == customerID
1819			if !everOwned {
1820				for _, c := range reassignsFor(s, p.ID) {
1821					if c.TargetCustomerID == customerID {
1822						everOwned = true
1823						break
1824					}
1825				}
1826			}
1827			if !everOwned {
1828				continue
1829			}
1830			involved := false
1831			// 沿更正链只在归属为该客户期间检查分配是否涉及该月：首次分配（首次
1832			// 登记客户）或某次以该客户为目标的更正的新分配涉及该月即可。
1833			if p.CustomerID == customerID && p.amountFor(month) > 0 {
1834				involved = true
1835			}
1836			if !involved {
1837				for _, c := range s.Corrections {
1838					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
1839						owner := c.TargetCustomerID
1840						if !c.Reassign {
1841							owner = paymentOwnerAt(s, p, c.Seq-1)
1842						}
1843						if owner == customerID {
1844							involved = true
1845							break
1846						}
1847					}
1848				}
1849			}
1850			if involved {
1851				list = append(list, p)
1852			}
1853		}
1854		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1855		return list
1856	}
1857	
1858	// paymentReceived 返回当前归属于指定客户、未撤销的全部收款，按最新分配在
1859	// 指定月份计入并扣除退款后的实收之和。收款可能经归属更正来自其他客户，
1860	// 归属按归属更正时间线取当前值；已整笔转出（当前归属为其他客户）或已撤销
1861	// 的收款不计入。各笔净额（分配减累计退款）均为非负整数，用非负 64 位加法
1862	// 累加，溢出时返回错误。
1863	func paymentReceived(s *state, customerID, month string) (int64, error) {
1864		var received int64
1865		for _, p := range s.Payments {
1866			if p.Revoked || paymentOwner(s, p) != customerID {
1867				continue
1868			}
1869			amt := allocAmountFor(currentAllocations(s, p), month) - refundedForMonth(s, p.ID, month)
1870			if amt <= 0 {
1871				continue
1872			}
1873			var err error
1874			received, err = add64(received, amt)
1875			if err != nil {
1876				return 0, err
1877			}
1878		}
1879		return received, nil
1880	}
1881	
1882	// refundsFor 返回某收款的全部退款，按操作序号升序。
1883	func refundsFor(s *state, paymentID string) []*refund {
1884		var list []*refund
1885		for _, r := range s.Refunds {
1886			if r.PaymentID == paymentID {
1887				list = append(list, r)
1888			}
1889		}
1890		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1891		return list
1892	}
1893	
1894	// refundedForMonth 返回某收款在指定月份的累计退款金额（分）；无退款时为 0。
1895	// 数据在载入时已校验累计不超退，合计不超过该月分配，不会溢出。
1896	func refundedForMonth(s *state, paymentID, month string) int64 {
1897		var total int64
1898		for _, r := range s.Refunds {
1899			if r.PaymentID == paymentID {
1900				total += allocAmountFor(r.Allocations, month)
1901			}
1902		}
1903		return total
1904	}
1905	
1906	// paymentHasRefunds 报告某收款是否已发生退款。首次退款后该收款的最新分配
1907	// 固定，不得再新增分配更正或整笔撤销。
1908	func paymentHasRefunds(s *state, paymentID string) bool {
1909		for _, r := range s.Refunds {
1910			if r.PaymentID == paymentID {
1911				return true
1912			}
1913		}
1914		return false
1915	}
1916	
1917	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
1918	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
1919	
1920	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
1921	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
1922	// [0, 有符号 64 位最大值] 内，全程整数运算。
1923	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
1924		var amounts []int64
1925		for _, a := range adjs {
1926			if !a.Revoked {
1927				amounts = append(amounts, a.Amount)
1928			}
1929		}
1930		net, err = sumSigned64(amounts...)
1931		if err != nil {
1932			return 0, 0, err
1933		}
1934		payable, err = addSigned64(b.TotalFee, net)
1935		if err != nil {
1936			return 0, 0, err
1937		}
1938		if payable < 0 {
1939			return 0, 0, errPayableOutOfRange
1940		}
1941		return net, payable, nil
1942	}
1943

