297	// parsedRow 是导入文件中一行解析后的候选用量。
298	type parsedRow struct {
299		line int // 文件中的行号（含表头），用于报错定位
300		rec  usageRecord
301		t    time.Time
302	}
303	
304	func cmdUsageImport(dir, file string) error {
305		var reader io.ReadCloser
306		var source string
307		if file == "-" {
308			reader = io.NopCloser(os.Stdin)
309			source = "标准输入"
310		} else {
311			f, err := os.Open(file)
312			if err != nil {
313				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
314			}
315			reader = f
316			source = file
317		}
318		defer reader.Close()
319	
320		rows, parseErrs := parseUsageFile(reader)
321	
322		s, err := loadStore(dir)
323		if err != nil {
324			return err
325		}
326	
327		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
328		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
329		var problems []string
330		problems = append(problems, parseErrs...)
331	
332		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
333		var ordered []*parsedRow
334		newCount, dupCount := 0, 0
335	
336		for _, r := range rows {
337			cust, ok := s.Customers[r.rec.CustomerID]
338			if !ok {
339				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
340				continue
341			}
342	
343			// 去重判定同时对“库中已有”和“本文件内已出现”生效，且先于暂停、
344			// 封账与金额预检：已存在记录（含已撤回记录）按客户、解析后的时间点
345			// 和数量与原内容判重，相同重放计入重复跳过——即使该月后来已封账、
346			// 暂停或后续方案计价会溢出也不受阻；已撤回记录的重放不会恢复记录。
347			var existing *usageRecord
348			if inStore, ok := s.Usage[r.rec.ID]; ok {
349				existing = inStore
350			} else if inBatch, ok := accepted[r.rec.ID]; ok {
351				existing = &inBatch.rec
352			}
353			if existing != nil {
354				if !sameUsage(existing, &r.rec, r.t) {
355					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
356						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
357					continue
358				}
359				dupCount++
360				continue
361			}
362	
363			// 以下为全新用量：暂停、封账及当前方案下金额预检只约束全新用量。
364			// 暂停月的新用量一律拒绝：按记录时间换算的 UTC 月份判断，处于任一
365			// 暂停区间（含起月、不含结束月）即整批失败并指出行号。
366			rowMonth := r.t.UTC().Format("2006-01")
367			if s.isSuspendedMonth(r.rec.CustomerID, rowMonth) {
368				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 处于暂停区间，暂停服务期间不接收用量（新用量 %q 被拒绝）",
369					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
370				continue
371			}
372			// 终止月（含）起的新用量一律拒绝：订阅已终止，永久结束后续服务。
373			if s.isTerminatedMonth(r.rec.CustomerID, rowMonth) {
374				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 不早于终止月 %s，订阅已终止不接收新用量（新用量 %q 被拒绝）",
375					r.line, r.rec.CustomerID, rowMonth, s.Terminations[r.rec.CustomerID].Month, r.rec.ID))
376				continue
377			}
378			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
379			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
380			// 溢出（金额单位：分）。
381			if cust.PlanID == "" {
382				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
383					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
384					continue
385				}
386			} else {
387				rec := r.rec
388				planID := s.effectivePlanID(cust, rowMonth)
389				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
390					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, rowMonth, planID, err))
391					continue
392				}
393			}
394	
395			// 全新标识：不得进入该客户已封账的 UTC 自然月。
396			if s.sealed(r.rec.CustomerID, rowMonth) {
397				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
398					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
399				continue
400			}
401	
402			rr := r
403			accepted[r.rec.ID] = rr
404			ordered = append(ordered, rr)
405			newCount++
406		}
407	
408		if len(problems) > 0 {
409			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
410		}
411	
412		for _, r := range ordered {
413			rec := r.rec
414			s.Usage[rec.ID] = &rec
415		}
416		if err := s.save(); err != nil {
417			return err
418		}
419		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
420		return nil
421	}
