692		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
693		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
694		// 涉及该月即纳入，即使后来被更正移出。
695		pays := paymentsEverFor(s, b.CustomerID, b.Month)
696		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
697		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
698		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
699		tiered := b.Pricing == "tiered"
700		if tiered {
701			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
702			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
703			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
704			fmt.Fprintln(stdout, "阶梯规则：")
705			for i, t := range b.PlanTiers {
706				if t.Limit == 0 {
707					fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
708				} else {
709					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
710				}
711			}
712		} else {
713			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
714		}
715		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
716		if tiered {
717			// 阶梯账单分列月费与用量费：原总金额 = 月费 + 全月用量费；
718			// 月费不计入总数量、各档金额或逐条小计。
719			usageFee := b.TotalFee - b.MonthlyFee
720			fmt.Fprintf(stdout, "月费：%d 分（%s，整月收取，不按天折算）\n", b.MonthlyFee, moneyFen(b.MonthlyFee))
721			fmt.Fprintf(stdout, "用量费：%d 分（%s）\n", usageFee, moneyFen(usageFee))
722			fmt.Fprintf(stdout, "原总金额：%d 分（%s，月费加全月用量费）\n", b.TotalFee, moneyFen(b.TotalFee))
723		} else {
724			fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
725		}
726		if tiered {
727			fmt.Fprintln(stdout, "各档合计：")
728			for i, tt := range b.TierTotals {
729				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
730					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
731			}
732		}
733		// 数据在载入时已校验一致，此处计算不会出错。
734		net, payable, _ := billTotals(b, adjs)
735		received, _ := paymentReceived(s, b.CustomerID, b.Month)
736		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
737		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
738		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
739		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
740		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
741		if len(b.Lines) == 0 {
742			fmt.Fprintln(stdout, "明细：无（本账期无用量，仅收取月费）")
743		} else {
744			fmt.Fprintln(stdout, "明细：")
745		}
746		for i, ln := range b.Lines {
747			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
748				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
749			// 阶梯账单逐条展示跨档分段的数量、单价与小计。
750			for j, seg := range ln.Segments {
751				fmt.Fprintf(stdout, "     分段 %d：第 %d 档 数量=%d 单价=%d 分 小计=%d 分（%s）\n",
752					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
753			}
754		}
755		if len(adjs) == 0 {
756			fmt.Fprintln(stdout, "调整与撤销历史：无")
757		} else {
758			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
759			for i, ev := range historyEvents(adjs) {
760				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
761			}
762		}
763		if len(pays) == 0 {
764			fmt.Fprintln(stdout, "收款与撤销历史：无")
765		} else {
766			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
767			for i, ev := range paymentHistoryEvents(s, pays, b.CustomerID, b.Month) {
768				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
769			}
770		}
771	}
