773	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
774	func historyEvents(adjs []*adjustment) []string {
775		type event struct {
776			seq  int64
777			text string
778		}
779		var events []event
780		for _, a := range adjs {
781			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
782				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
783			if a.Revoked {
784				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
785					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
786			}
787		}
788		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
789		out := make([]string, len(events))
790		for i, ev := range events {
791			out[i] = ev.text
792		}
793		return out
794	}
