810	// paymentHistoryEvents 把收款登记、分配更正、归属更正（转出/转入）、整笔撤销
811	// 与退款展开为按操作序号排序的可读历史条目。customerID/month 为当前展示账单：
812	// 收款可能经归属更正在客户间整笔转移，本函数沿归属时间线只列与该账单客户
813	// 相关的一侧——登记事件仅首次登记客户展示，归属更正在转出侧展示 X→0、
814	// 转入侧展示 0→X，同客户分配更正展示前后变化，退款与撤销只展示发生时归属
815	// 该客户的一侧；曾涉及本账单的收款在归属该客户期间被更正移出本月后撤销，
816	// 仍保留零金额撤销事件。
817	func paymentHistoryEvents(s *state, pays []*payment, customerID, month string) []string {
818		type event struct {
819			seq  int64
820			text string
821		}
822		var events []event
823		for _, p := range pays {
824			// 登记事件只属于首次登记客户。
825			if p.CustomerID == customerID {
826				if alloc := p.amountFor(month); alloc > 0 {
827					events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（登记客户 %s，当前归属客户 %s）",
828						p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID, paymentOwner(s, p))})
829				}
830			}
831			// 沿归属时间线回放该收款的全部更正。
832			owner := p.CustomerID
833			running := p.Allocations
834			for _, c := range correctionsFor(s, p.ID) {
835				before := allocAmountFor(running, month)
836				after := allocAmountFor(c.Allocations, month)
837				if c.Reassign {
838					if owner == customerID && before > 0 {
839						events = append(events, event{c.Seq, fmt.Sprintf("归属更正 %s：原因：%s（关联收款 %s，整笔转出至客户 %s，本账单分配 %d 分 → 0 分）",
840							c.ID, c.Reason, p.ID, c.TargetCustomerID, before)})
841					}
842					if c.TargetCustomerID == customerID && after > 0 {
843						events = append(events, event{c.Seq, fmt.Sprintf("归属更正 %s：原因：%s（关联收款 %s，自客户 %s 整笔转入，本账单分配 0 分 → %d 分）",
844							c.ID, c.Reason, p.ID, owner, after)})
845					}
846					owner = c.TargetCustomerID
847				} else if owner == customerID && (before > 0 || after > 0) {
848					events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
849						c.ID, c.Reason, p.ID, before, after)})
850				}
851				running = c.Allocations
852			}
853			// 整笔撤销只在撤销时归属客户一侧取最新分配金额；曾在归属期间涉及本
854			// 账单（即使后来被更正移出或整笔转出）的收款，撤销后仍保留零金额撤销
855			// 事件，与 bill ledger 一致。pays 已按“曾涉及”筛入。
856			if p.Revoked {
857				revokeOwner := owner // 回放结束时的归属即撤销发生时归属（撤销后不得再有更正）
858				if revokeOwner == customerID {
859					amt := allocAmountFor(running, month)
860					events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
861						p.ID, p.RevokeReason, p.ID, p.Total, amt)})
862				} else {
863					events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，撤销时归属客户 %s，总额 %d 分，本账单分配 0 分）",
864						p.ID, p.RevokeReason, p.ID, revokeOwner, p.Total)})
865				}
866			}
867			// 退款只减少退款发生时归属客户的本账单实收；退款不可撤销。
868			for _, r := range refundsFor(s, p.ID) {
869				if paymentOwnerAt(s, p, r.Seq) != customerID {
870					continue
871				}
872				amt := allocAmountFor(r.Allocations, month)
873				if amt <= 0 {
874					continue
875				}
876				events = append(events, event{r.Seq, fmt.Sprintf("退款 %s：原因：%s（关联收款 %s，本账单退款 %d 分（%s））",
877					r.ID, r.Reason, p.ID, amt, moneyFen(amt))})
878			}
879		}
880		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
881		out := make([]string, len(events))
882		for i, ev := range events {
883			out[i] = ev.text
884		}
885		return out
886	}
