895	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
896	func parseAmount(text string) (int64, error) {
897		text = strings.TrimSpace(text)
898		amount, err := strconv.ParseInt(text, 10, 64)
899		if err != nil {
900			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
901		}
902		if amount == 0 {
903			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
904		}
905		return amount, nil
906	}
