908	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
909		if !validMonth(month) {
910			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
911		}
912		if strings.TrimSpace(adjID) == "" {
913			return fmt.Errorf("调整标识不能为空")
914		}
915		amount, err := parseAmount(amountText)
916		if err != nil {
917			return err
918		}
919		if strings.TrimSpace(reason) == "" {
920			return fmt.Errorf("调整原因不能为空")
921		}
922	
923		s, err := loadStore(dir)
924		if err != nil {
925			return err
926		}
927		if _, ok := s.Customers[customerID]; !ok {
928			return fmt.Errorf("客户标识 %q 不存在", customerID)
929		}
930		b, ok := s.Bills[billKey(customerID, month)]
931		if !ok {
932			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
933		}
934	
935		if existing, ok := s.Adjustments[adjID]; ok {
936			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
937			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
938			if existing.CustomerID == customerID && existing.Month == month &&
939				existing.Amount == amount && existing.Reason == reason {
940				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
941				printAdjustment(existing, s)
942				return nil
943			}
944			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
945				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
946		}
947	
948		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
949		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
950		// 不占用该调整标识。
951		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
952		if err != nil {
953			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
954		}
955		received, err := paymentReceived(s, customerID, month)
956		if err != nil {
957			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
958		}
959		newPayable, err := addSigned64(payable, amount)
960		if err != nil {
961			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
962		}
963		if newPayable < 0 {
964			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
965		}
966		if newPayable < received {
967			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
968				newPayable, received, payable, amount)
969		}
970	
971		a := &adjustment{
972			ID:         adjID,
973			CustomerID: customerID,
974			Month:      month,
975			Amount:     amount,
976			Reason:     reason,
977			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
978		}
979		s.NextSeq++
980		a.Seq = s.NextSeq
981		s.Adjustments[adjID] = a
982	
983		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
984		// 该调整标识不被占用。
985		if err := s.save(); err != nil {
986			delete(s.Adjustments, adjID)
987			s.NextSeq--
988			return err
989		}
990		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
991			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
992		printAdjustment(a, s)
993		return nil
994	}
