996	func cmdBillRevoke(dir, adjID, reason string) error {
997		if strings.TrimSpace(adjID) == "" {
998			return fmt.Errorf("调整标识不能为空")
999		}
1000		if strings.TrimSpace(reason) == "" {
1001			return fmt.Errorf("撤销原因不能为空")
1002		}
1003	
1004		s, err := loadStore(dir)
1005		if err != nil {
1006			return err
1007		}
1008		a, ok := s.Adjustments[adjID]
1009		if !ok {
1010			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
1011		}
1012	
1013		if a.Revoked {
1014			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
1015			// 改用其他原因则拒绝。
1016			if a.RevokeReason == reason {
1017				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
1018				printAdjustment(a, s)
1019				return nil
1020			}
1021			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
1022		}
1023	
1024		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
1025		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
1026		// 改变余额后重试。
1027		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
1028		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
1029		if err != nil {
1030			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
1031		}
1032		received, err := paymentReceived(s, a.CustomerID, a.Month)
1033		if err != nil {
1034			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
1035		}
1036		neg, err := neg64(a.Amount)
1037		if err != nil {
1038			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
1039		}
1040		newPayable, err := addSigned64(payable, neg)
1041		if err != nil {
1042			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
1043				payable, a.Amount)
1044		}
1045		if newPayable < 0 {
1046			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
1047				newPayable, payable, a.Amount)
1048		}
1049		if newPayable < received {
1050			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
1051				newPayable, received, payable, a.Amount)
1052		}
1053	
1054		a.Revoked = true
1055		a.RevokeReason = reason
1056		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1057		s.NextSeq++
1058		a.RevokeSeq = s.NextSeq
1059	
1060		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1061		if err := s.save(); err != nil {
1062			a.Revoked = false
1063			a.RevokeReason = ""
1064			a.RevokedAt = ""
1065			a.RevokeSeq = 0
1066			s.NextSeq--
1067			return err
1068		}
1069		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
1070			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
1071		printAdjustment(a, s)
1072		return nil
1073	}
