1092	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
1093	func parsePositiveAmount(text string) (int64, error) {
1094		text = strings.TrimSpace(text)
1095		amount, err := strconv.ParseInt(text, 10, 64)
1096		if err != nil {
1097			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
1098		}
1099		if amount <= 0 {
1100			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
1101		}
1102		return amount, nil
1103	}
