1105	func cmdBillPay(dir, customerID, month, payID, amountText, note string) error {
1106		if !validMonth(month) {
1107			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1108		}
1109		amount, err := parsePositiveAmount(amountText)
1110		if err != nil {
1111			return err
1112		}
1113		// 单账单收款视为只有一项分配的汇款，与 bill remit 共用同一核心。
1114		return registerPayment(dir, customerID, payID, amount, note,
1115			[]paymentAllocation{{Month: month, Amount: amount}})
