1118	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
1119		total, err := parsePositiveAmount(totalText)
1120		if err != nil {
1121			return err
1122		}
1123		allocs, err := parseAllocations(allocArgs)
1124		if err != nil {
1125			return err
1126		}
1127		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
1128		var sum int64
1129		for _, al := range allocs {
1130			sum, err = add64(sum, al.Amount)
1131			if err != nil {
1132				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
1133			}
1134		}
1135		if sum != total {
1136			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
1137		}
1138		return registerPayment(dir, customerID, payID, total, note, allocs)
1139	}
