1143	// cmdBillRemitAuto 登记一笔自动分配汇款：调用方只提供客户、收款标识、总金额
1144	// 与备注，月份金额由工具确定——首次登记只选择该客户当前已有账单，按 UTC
1145	// 账期月升序依次偿还当前未收余额（调整、最新收款分配、撤销及退款后的净额），
1146	// 跳过余额为 0 的月份，前一月份还清后才分配下一月，最后一月可部分偿还；
1147	// 不补结算、不跨客户、不留未分配款项。无欠款或总金额超过全部欠款时整笔拒绝。
1148	func cmdBillRemitAuto(dir, customerID, payID, totalText, note string) error {
1149		total, err := parsePositiveAmount(totalText)
1150		if err != nil {
1151			return err
1152		}
1153		if strings.TrimSpace(payID) == "" {
1154			return fmt.Errorf("收款标识不能为空")
1155		}
1156		if strings.TrimSpace(note) == "" {
1157			return fmt.Errorf("收款备注不能为空")
1158		}
1159	
1160		s, err := loadStore(dir)
1161		if err != nil {
1162			return err
1163		}
1164		if _, ok := s.Customers[customerID]; !ok {
1165			return fmt.Errorf("客户标识 %q 不存在", customerID)
1166		}
1167	
1168		if existing, ok := s.Payments[payID]; ok {
1169			// 自动登记按客户、总金额、备注判重：相同请求返回原收款及当前状态，
1170			// 不写盘、不重新分配、不增加序号；已撤销或已退款的仍返回当前状态，
1171			// 不恢复旧分配或已退、已撤销金额。
1172			if existing.Auto && existing.CustomerID == customerID &&
1173				existing.Total == total && existing.Note == note {
1174				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同（自动分配登记），返回原收款及当前状态（不写盘、不重新分配、不增加序号）：\n\n", payID)
1175				printAutoPayment(s, existing)
1176				return nil
1177			}
1178			// 同一标识在自动与显式分配登记间复用拒绝；内容不同同样拒绝。
1179			if !existing.Auto {
1180				return fmt.Errorf("收款标识 %q 已由显式分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1181					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1182			}
1183			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q），拒绝复用",
1184				payID, existing.CustomerID, existing.Total, existing.Note)
1185		}
1186	
1187		// 首次登记的自动分配由 remit-auto 与整批导入共用的 autoAllocate 确定。
1188		allocs, err := autoAllocate(s, customerID, total)
1189		if err != nil {
1190			return err
1191		}
1192	
1193		// 成功保存为一笔普通收款及首次自动分配：占用一个账后全局序号，
1194		// 不按月份拆成多笔；可沿用分配更正、整笔撤销、部分退款及退款后
1195		// 固定分配的规则。
1196		p := &payment{
1197			ID:          payID,
1198			CustomerID:  customerID,
1199			Total:       total,
1200			Note:        note,
1201			Allocations: allocs,
1202			Auto:        true,
1203			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1204		}
1205		s.NextSeq++
1206		p.Seq = s.NextSeq
1207		s.Payments[payID] = p
1208	
1209		// 收款记录、首次分配与序号在同一次原子保存中持久化；保存失败则一切
1210		// 不生效，该收款标识与序号不被占用，可原样重试。
1211		if err := s.save(); err != nil {
1212			delete(s.Payments, payID)
1213			s.NextSeq--
1214			return err
1215		}
1216		fmt.Fprintf(stdout, "已按最早欠款账期自动分配并登记收款 %q（总额 %d 分，%s；一次操作，占用一个账后序号）：\n\n",
1217			payID, total, moneyFen(total))
1218		printAutoPayment(s, p)
1219		return nil
1220	}
