1222	// printAutoPayment 输出一笔自动分配登记的收款：收款标识、总额、备注、当前
1223	// 状态、首次分配与最新分配，以及这两份分配所涉月份的当前余额。首次分配
1224	// 永久保留；最新分配经更正变化时以最新为准，退款与撤销不改变首次分配。
1225	func printAutoPayment(s *state, p *payment) {
1226		current := currentAllocations(s, p)
1227		currentOwner := paymentOwner(s, p)
1228		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1229		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1230		if currentOwner != p.CustomerID {
1231			fmt.Fprintf(stdout, "当前归属客户：%s（首次登记客户 %s，经收款客户归属更正转移）\n", currentOwner, p.CustomerID)
1232		}
1233		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1234		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1235		if p.Revoked {
1236			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1237		} else {
1238			fmt.Fprintf(stdout, "当前状态：实收中\n")
1239		}
1240		fmt.Fprintf(stdout, "首次分配（登记时按最早欠款账期自动确定，永久保留）：%s\n", formatAllocations(p.Allocations))
1241		if sameAllocations(current, p.Allocations) && currentOwner == p.CustomerID {
1242			fmt.Fprintf(stdout, "最新分配：%s（与首次分配相同）\n", formatAllocations(current))
1243		} else {
1244			fmt.Fprintf(stdout, "最新分配（经更正，以最新为准）：%s\n", formatAllocations(current))
1245			if currentOwner != p.CustomerID {
1246				fmt.Fprintf(stdout, "最新分配归属客户：%s（首次登记客户 %s，经收款客户归属更正转移）\n", currentOwner, p.CustomerID)
1247			}
1248		}
1249		fmt.Fprintln(stdout, "首次与最新分配所涉月份当前余额：")
1250		for _, m := range unionMonths(p.Allocations, current) {
1251			// 月份余额按当时归属客户：最新分配月份属于当前归属客户；仅首次分配
1252			// 涉及而最新分配已不涉及的月份属于首次登记客户（经归属更正转出）。
1253			monthOwner := p.CustomerID
1254			if allocAmountFor(current, m) > 0 {
1255				monthOwner = currentOwner
1256			}
1257			b := s.Bills[billKey(monthOwner, m)] // 载入时已校验存在
1258			_, payable, _ := billTotals(b, adjustmentsFor(s, monthOwner, m))
1259			received, _ := paymentReceived(s, monthOwner, m)
1260			fmt.Fprintf(stdout, "  月份 %s：首次分配 %d 分，最新分配 %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1261				m, allocAmountFor(p.Allocations, m), allocAmountFor(current, m),
1262				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1263		}
1264	}
