1266	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
1267	// 月份不得重复，每项金额为正整数分。
1268	func parseAllocations(args []string) ([]paymentAllocation, error) {
1269		if len(args) == 0 {
1270			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
1271		}
1272		seen := make(map[string]bool)
1273		allocs := make([]paymentAllocation, 0, len(args))
1274		for _, arg := range args {
1275			parts := strings.Split(arg, ":")
1276			if len(parts) != 2 {
1277				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1278			}
1279			month := strings.TrimSpace(parts[0])
1280			if !validMonth(month) {
1281				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1282			}
1283			if seen[month] {
1284				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1285			}
1286			seen[month] = true
1287			amount, err := parsePositiveAmount(parts[1])
1288			if err != nil {
1289				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1290			}
1291			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1292		}
1293		return allocs, nil
1294	}
1295	
1296	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1297	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1298	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1299		if strings.TrimSpace(payID) == "" {
1300			return fmt.Errorf("收款标识不能为空")
1301		}
1302		if strings.TrimSpace(note) == "" {
1303			return fmt.Errorf("收款备注不能为空")
1304		}
1305		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1306		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1307	
1308		s, err := loadStore(dir)
1309		if err != nil {
1310			return err
1311		}
1312		if _, ok := s.Customers[customerID]; !ok {
1313			return fmt.Errorf("客户标识 %q 不存在", customerID)
1314		}
1315		for _, al := range allocs {
1316			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1317				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1318			}
1319		}
1320	
1321		if existing, ok := s.Payments[payID]; ok {
1322			// 自动与显式分配登记之间不得复用同一收款标识：标识由 bill remit-auto
1323			// 占用时，bill pay / bill remit 一律拒绝（即使内容碰巧相同）。
1324			if existing.Auto {
1325				return fmt.Errorf("收款标识 %q 已由自动分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1326					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1327			}
1328			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1329			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1330			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1331			if samePaymentContent(existing, customerID, total, note, allocs) {
1332				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1333				printPayment(existing, s)
1334				return nil
1335			}
1336			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1337				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1338		}
1339	
1340		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1341		for _, al := range allocs {
1342			b := s.Bills[billKey(customerID, al.Month)]
1343			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1344			if err != nil {
1345				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1346			}
1347			received, err := paymentReceived(s, customerID, al.Month)
1348			if err != nil {
1349				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1350			}
1351			if payable == 0 {
1352				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1353			}
1354			if al.Amount > payable-received {
1355				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1356					al.Amount, payable-received, customerID, al.Month, payable, received)
1357			}
1358		}
1359	
1360		p := &payment{
1361			ID:          payID,
1362			CustomerID:  customerID,
1363			Total:       total,
1364			Note:        note,
1365			Allocations: allocs,
1366			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1367		}
1368		s.NextSeq++
1369		p.Seq = s.NextSeq
1370		s.Payments[payID] = p
1371	
1372		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1373		// 一切不生效，该收款标识不被占用。
1374		if err := s.save(); err != nil {
1375			delete(s.Payments, payID)
1376			s.NextSeq--
1377			return err
1378		}
1379		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1380		printAllocationBalances(s, p, allocs)
1381		fmt.Fprintln(stdout)
1382		printPayment(p, s)
1383		return nil
1384	}
1385	
1386	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
1387	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
1388	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
1389		if p.CustomerID != customerID || p.Total != total || p.Note != note {
1390			return false
1391		}
1392		return sameAllocations(p.Allocations, allocs)
1393	}
