1395	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1396	func sameAllocations(a, b []paymentAllocation) bool {
1397		if len(a) != len(b) {
1398			return false
1399		}
1400		for _, al := range b {
1401			if allocAmountFor(a, al.Month) != al.Amount {
1402				return false
1403			}
1404		}
1405		return true
1406	}
