1408	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1409	func formatAllocations(allocs []paymentAllocation) string {
1410		parts := make([]string, len(allocs))
1411		for i, al := range allocs {
1412			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1413		}
1414		return strings.Join(parts, ",")
1415	}
