1417	// printAllocationBalances 输出给定分配列表每个分配月份当前的实收与未收余额。
1418	// 分配所属客户取收款当前归属（经归属更正后可能异于首次登记客户）。
1419	func printAllocationBalances(s *state, p *payment, allocs []paymentAllocation) {
1420		owner := paymentOwner(s, p)
1421		for _, al := range allocs {
1422			b := s.Bills[billKey(owner, al.Month)] // 载入时已校验存在
1423			_, payable, _ := billTotals(b, adjustmentsFor(s, owner, al.Month))
1424			received, _ := paymentReceived(s, owner, al.Month)
1425			fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，实收 %d 分（%s），未收余额 %d 分（%s）\n",
1426				al.Month, al.Amount, received, moneyFen(received), payable-received, moneyFen(payable-received))
1427		}
1428	}
