1430	func cmdBillUnpay(dir, payID, reason string) error {
1431		if strings.TrimSpace(payID) == "" {
1432			return fmt.Errorf("收款标识不能为空")
1433		}
1434		if strings.TrimSpace(reason) == "" {
1435			return fmt.Errorf("撤销原因不能为空")
1436		}
1437	
1438		s, err := loadStore(dir)
1439		if err != nil {
1440			return err
1441		}
1442		p, ok := s.Payments[payID]
1443		if !ok {
1444			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1445		}
1446	
1447		if p.Revoked {
1448			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1449			// 改用其他原因则拒绝。
1450			if p.RevokeReason == reason {
1451				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1452				printPayment(p, s)
1453				return nil
1454			}
1455			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1456		}
1457	
1458		// 首次退款后该收款的最新分配固定，拒绝整笔撤销；退款记录永久保留且
1459		// 不可撤销，实收按扣除退款后的余额继续计算。无退款的收款仍按原规则
1460		// 处理。
1461		if paymentHasRefunds(s, payID) {
1462			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝整笔撤销；如需退回余款请继续登记部分退款", payID)
1463		}
1464	
1465		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1466		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1467		// 分配、更正与撤销原因永久保留。
1468		p.Revoked = true
1469		p.RevokeReason = reason
1470		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1471		s.NextSeq++
1472		p.RevokeSeq = s.NextSeq
1473	
1474		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1475		if err := s.save(); err != nil {
1476			p.Revoked = false
1477			p.RevokeReason = ""
1478			p.RevokedAt = ""
1479			p.RevokeSeq = 0
1480			s.NextSeq--
1481			return err
1482		}
1483		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1484		printAllocationBalances(s, p, currentAllocations(s, p))
1485		fmt.Fprintln(stdout)
1486		printPayment(p, s)
1487		return nil
1488	}
