1490	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1491	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1492	// 各月应付/实收取自当前库状态。
1493	func printPayment(p *payment, s *state) {
1494		owner := paymentOwner(s, p)
1495		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1496		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1497		if owner != p.CustomerID {
1498			fmt.Fprintf(stdout, "当前归属客户：%s（首次登记客户 %s，经收款客户归属更正转移；首次登记身份不改写）\n", owner, p.CustomerID)
1499		}
1500		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1501		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1502		if p.Revoked {
1503			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1504		} else {
1505			fmt.Fprintf(stdout, "当前状态：实收中\n")
1506		}
1507		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1508		for i, al := range p.Allocations {
1509			b := s.Bills[billKey(p.CustomerID, al.Month)] // 首次登记客户的账单，载入时已校验存在
1510			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1511			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1512			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1513				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1514		}
1515		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1516			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1517				len(corrs), formatAllocations(currentAllocations(s, p)))
1518			if owner != p.CustomerID {
1519				fmt.Fprintf(stdout, "最新分配归属客户：%s\n", owner)
1520			}
1521		}
1522		if refs := refundsFor(s, p.ID); len(refs) > 0 {
1523			current := currentAllocations(s, p)
1524			fmt.Fprintf(stdout, "退款记录（%d 笔，永久保留、不可撤销；首次退款后最新分配已固定）：\n", len(refs))
1525			for _, r := range refs {
1526				fmt.Fprintf(stdout, "  退款 %s：%s，原因：%s\n", r.ID, formatAllocations(r.Allocations), r.Reason)
1527			}
1528			fmt.Fprintln(stdout, "各月剩余可退额（最新分配减累计退款）：")
1529			for _, al := range current {
1530				refunded := refundedForMonth(s, p.ID, al.Month)
1531				fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，累计已退 %d 分，剩余可退 %d 分（%s）\n",
1532					al.Month, al.Amount, refunded, al.Amount-refunded, moneyFen(al.Amount-refunded))
1533			}
1534		}
1535	}
