1537	// --- 收款分配更正 ---
1538	
1539	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1540		if strings.TrimSpace(payID) == "" {
1541			return fmt.Errorf("收款标识不能为空")
1542		}
1543		if strings.TrimSpace(corrID) == "" {
1544			return fmt.Errorf("更正标识不能为空")
1545		}
1546		if strings.TrimSpace(reason) == "" {
1547			return fmt.Errorf("更正原因不能为空")
1548		}
1549		allocs, err := parseAllocations(allocArgs)
1550		if err != nil {
1551			return err
1552		}
1553		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1554		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1555	
1556		s, err := loadStore(dir)
1557		if err != nil {
1558			return err
1559		}
1560		p, ok := s.Payments[payID]
1561		if !ok {
1562			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1563		}
1564	
1565		if existing, ok := s.Corrections[corrID]; ok {
1566			// 更正标识与 bill reassign 共用且不可跨类型复用：被归属更正占用时
1567			// 一律拒绝，不能当作同内容重放。
1568			if existing.Reassign {
1569				return fmt.Errorf("更正标识 %q 已由归属更正占用（目标收款=%s 目标客户=%s 新分配=%s），分配更正与归属更正之间不得复用标识",
1570					corrID, existing.PaymentID, existing.TargetCustomerID, formatAllocations(existing.Allocations))
1571			}
1572			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1573			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1574			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1575			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1576				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1577				printCorrection(existing, s)
1578				return nil
1579			}
1580			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1581				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1582		}
1583	
1584		// 新增更正只允许未撤销收款。
1585		if p.Revoked {
1586			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1587		}
1588	
1589		// 首次退款后该收款的最新分配固定，拒绝新增分配更正；已有更正的相同
1590		// 重放已在上面按原记录返回，不受此限。无退款的收款仍按原规则处理。
1591		if paymentHasRefunds(s, payID) {
1592			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝新增分配更正", payID)
1593		}
1594	
1595		// 分配更正只调整当前归属客户的月份：收款可能已被归属更正转给其他客户，
1596		// 这里以当前归属为准，原登记客户（payment.CustomerID）不再参与。
1597		owner := paymentOwner(s, p)
1598	
1599		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1600		var sum int64
1601		for _, al := range allocs {
1602			sum, err = add64(sum, al.Amount)
1603			if err != nil {
1604				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1605			}
1606		}
1607		if sum != p.Total {
1608			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1609		}
1610		// 新分配月份须是当前归属客户的已结算账单。
1611		for _, al := range allocs {
1612			if _, ok := s.Bills[billKey(owner, al.Month)]; !ok {
1613				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到当前归属客户已存在账单", owner, al.Month)
1614			}
1615		}
1616	
1617		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1618		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1619		current := currentAllocations(s, p)
1620		for _, m := range unionMonths(current, allocs) {
1621			b := s.Bills[billKey(owner, m)] // 载入时已校验存在
1622			_, payable, err := billTotals(b, adjustmentsFor(s, owner, m))
1623			if err != nil {
1624				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", owner, m, err)
1625			}
1626			received, err := paymentReceived(s, owner, m)
1627			if err != nil {
1628				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", owner, m, err)
1629			}
1630			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1631			received -= allocAmountFor(current, m)
1632			received, err = add64(received, allocAmountFor(allocs, m))
1633			if err != nil {
1634				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", owner, m)
1635			}
1636			if received > payable {
1637				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1638					owner, m, received, payable)
1639			}
1640		}
1641	
1642		c := &correction{
1643			ID:          corrID,
1644			PaymentID:   payID,
1645			Reason:      reason,
1646			Allocations: allocs,
1647			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1648		}
1649		s.NextSeq++
1650		c.Seq = s.NextSeq
1651		s.Corrections[corrID] = c
1652	
1653		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1654		// 一切不生效，该更正标识不被占用。
1655		if err := s.save(); err != nil {
1656			delete(s.Corrections, corrID)
1657			s.NextSeq--
1658			return err
1659		}
1660		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1661		printCorrection(c, s)
1662		return nil
1663	}
1664	
1665	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1666	func unionMonths(a, b []paymentAllocation) []string {
1667		set := make(map[string]bool, len(a)+len(b))
1668		for _, al := range a {
1669			set[al.Month] = true
1670		}
1671		for _, al := range b {
1672			set[al.Month] = true
1673		}
1674		months := make([]string, 0, len(set))
1675		for m := range set {
1676			months = append(months, m)
1677		}
1678		sort.Strings(months)
1679		return months
1680	}
1681	
1682	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1683	// 新分配，或（首次更正时）收款的原始分配。
1684	func allocationBefore(s *state, c *correction) []paymentAllocation {
1685		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1686		var latest *correction
1687		for _, o := range s.Corrections {
1688			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1689				latest = o
1690			}
1691		}
1692		if latest != nil {
1693			before = latest.Allocations
1694		}
1695		return before
1696	}
1697	
1698	// printCorrection 输出单笔同客户分配更正记录：关联收款、标识、原因、完整
1699	// 前后分配，以及前后分配涉及月份的当前余额。分配更正只调整更正发生时当前
1700	// 归属客户的月份；收款可能来自更早的归属更正，故月份余额按当时归属客户查询。
1701	func printCorrection(c *correction, s *state) {
1702		p := s.Payments[c.PaymentID] // 载入时已校验存在
1703		before := allocationBefore(s, c)
1704		owner := paymentOwnerAt(s, p, c.Seq) // 分配更正不改变归属，即更正后当前客户
1705		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1706		fmt.Fprintf(stdout, "关联收款：%s（原登记客户 %s，本更正归属客户 %s，总额 %d 分（%s），备注：%s）\n",
1707			p.ID, p.CustomerID, owner, p.Total, moneyFen(p.Total), p.Note)
1708		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1709		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1710		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1711		fmt.Fprintln(stdout, "涉及月份当前余额：")
1712		for _, m := range unionMonths(before, c.Allocations) {
1713			b := s.Bills[billKey(owner, m)] // 载入时已校验存在
1714			_, payable, _ := billTotals(b, adjustmentsFor(s, owner, m))
1715			received, _ := paymentReceived(s, owner, m)
1716			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1717				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1718				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1719		}
1720	}
1721	
1722	// --- 账后对账流水 ---
1723	
1724	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1725	// 分配更正、归属更正（转出或转入）、撤销收款或退款。事件按全局操作序号升序
1726	// 回放；撤销在其发生序号抵消对应原操作，已撤销记录在撤销之前仍计入，不按
1727	// 当前撤销状态删除原事件；更正在其发生序号把关联收款在本账单的分配由前值
1728	// 替换为后值；归属更正在同一序号把实收整笔转出原客户或转入目标客户（本账单
1729	// 只看到自己一侧的正负增量）；退款在其发生序号减少本账单实收，不可撤销。
1730	type ledgerEvent struct {
1731		seq           int64  // 全局操作序号（调整/收款/更正/退款及其撤销共用）
1732		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 归属更正 / 撤销收款 / 退款
1733		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1734		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1735		deltaReceived int64  // 对实收的影响（分，带符号）
1736		note          string // 原因（调整/更正类）或备注（收款类）
1737		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1738		payTotal      int64  // 收款类事件：汇款总额
1739		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配；退款事件为本账单退款额）
1740		payID         string // 更正/退款事件：关联收款标识
1741		fromCustomer  string // 归属更正事件：转出客户（本账单一侧即转出侧时等于账单客户）
1742		toCustomer    string // 归属更正事件：转入客户（本账单一侧即转入侧时等于账单客户）
1743		beforeAlloc   int64  // 更正事件：本账单更正前分配
1744		afterAlloc    int64  // 更正事件：本账单更正后分配
1745		afterPayable  int64  // 事件后的应付（回放时填充）
1746		afterReceived int64  // 事件后的实收（回放时填充）
1747	}
1748	
1749	// billLedger 返回目标账单的一条按操作序号升序的账后流水，事件之后的三项
1750	// 余额已逐步填充。业务归属、金额影响（调整/撤销/收款/更正/撤销收款/退款）
1751	// 与完整性核验都来自与 bill reconcile 共用的 postbill 计算，本处只取该账单
1752	// 那一条流水：
1753	//
1754	//   - 以原总金额为初始应付、零实收为起点；
1755	//   - 回放覆盖完整流水（不受查询截止序号限制），序号重复、撤销先于原操作，
1756	//     或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号 64 位最大值，都视为
1757	//     数据异常并拒绝，即使异常发生在截止序号之后——只检查最终余额会放过
1758	//     中间越界的存档；
1759	//   - 曾涉及该账单的收款在被更正移出该月后，仍保留零金额撤销事件。
1760	//
1761	// 只读：不修改库、不占用序号、不新增记录。
1762	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1763		ops, err := postbillOps(s, b.CustomerID)
1764		if err != nil {
1765			return nil, err
1766		}
1767		ledgers, err := verifyPostbillLedgers(ops, []*bill{b})
1768		if err != nil {
1769			return nil, err
1770		}
1771		return ledgers[b.Month], nil
1772	}
1773	
1774	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1775		if !validMonth(month) {
1776			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1777		}
1778		s, err := loadStore(dir)
1779		if err != nil {
1780			return err
1781		}
1782		cust, ok := s.Customers[customerID]
1783		if !ok {
1784			return fmt.Errorf("客户标识 %q 不存在", customerID)
1785		}
1786		b, ok := s.Bills[billKey(customerID, month)]
1787		if !ok {
1788			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1789		}
1790	
1791		// 截止序号使用调整/收款/更正/退款及其撤销共用的已保存全局序号：省略表示最新，
1792		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1793		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1794		cutoff := s.NextSeq
1795		cutoffDesc := "省略，按最新"
1796		if hasCutoff {
1797			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1798			if perr != nil {
1799				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1800			}
1801			if v < 0 {
1802				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1803			}
1804			if v > s.NextSeq {
1805				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1806			}
1807			cutoff = v
1808			cutoffDesc = "指定"
1809		}
1810	
1811		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1812		// 拒绝，不输出部分正常的报告。
1813		events, err := billLedger(s, b)
1814		if err != nil {
1815			return err
1816		}
1817		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1818		return nil
1819	}
1820	
1821	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1822		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1823		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1824		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1825		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1826		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1827		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1828		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1829			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1830	
1831		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1832		payable, received := b.TotalFee, int64(0)
1833		var shown []ledgerEvent
1834		for _, ev := range events {
1835			if ev.seq > cutoff {
1836				continue
1837			}
1838			shown = append(shown, ev)
1839			payable, received = ev.afterPayable, ev.afterReceived
1840		}
1841		if len(shown) == 0 {
1842			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1843		} else {
1844			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1845			for i, ev := range shown {
1846				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1847			}
1848		}
1849		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1850			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1851	}
1852	
1853	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1854	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1855	// 说明汇款总额与本账单分配。
1856	func formatLedgerEvent(ev ledgerEvent) string {
1857		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1858			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1859		switch ev.kind {
1860		case "调整":
1861			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1862				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1863		case "撤销调整":
1864			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1865				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1866		case "收款":
1867			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1868				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1869		case "更正":
1870			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1871				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1872		case "归属更正":
1873			// 本账单只看到自己一侧：deltaReceived 为负即转出侧，为正即转入侧。
1874			if ev.deltaReceived < 0 {
1875				return fmt.Sprintf("序号 %d 归属更正 %s：实收 %+d 分（%s，关联收款 %s，整笔转出至客户 %s，本账单转出 %d 分），原因：%s → %s",
1876					ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.toCustomer, -ev.deltaReceived, ev.note, after)
1877			}
1878			return fmt.Sprintf("序号 %d 归属更正 %s：实收 %+d 分（%s，关联收款 %s，自客户 %s 整笔转入，本账单转入 %d 分），原因：%s → %s",
1879				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.fromCustomer, ev.deltaReceived, ev.note, after)
1880		case "退款":
1881			return fmt.Sprintf("序号 %d 退款 %s：实收 %+d 分（%s，关联收款 %s，本账单退款 %d 分），原因：%s → %s",
1882				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.payAlloc, ev.note, after)
1883		default: // 撤销收款
1884			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1885				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1886		}
1887	}
1888

