60		// 方案变化或替代记录已撤回，都不能阻止相同重放，也不能恢复任何记录。
61		if uc, ok := s.UsageCorrections[origID]; ok {
62			if uc.ReplacementID == newID && uc.NewCustomerID == newCustomerID &&
63				uc.NewQuantity == qty && uc.Reason == reason {
64				savedT, perr := time.Parse(time.RFC3339, uc.NewTime)
65				if perr == nil && savedT.Equal(t) {
66					fmt.Fprintf(stdout, "用量 %q 的更正已存在且内容相同，返回原更正及两条记录当前状态（不写盘）：\n\n", origID)
67					printUsageCorrection(s, uc)
68					return nil
69				}
70			}
71			return fmt.Errorf("用量 %q 已更正（替代记录 %q，客户 %s，时间 %s，数量 %d，原因 %q），"+
72				"新标识、客户、解析后的时间点、数量或原因任一项不同即拒绝；每条原用量只能更正一次，更正不可撤销",
73				origID, uc.ReplacementID, uc.NewCustomerID, uc.NewTime, uc.NewQuantity, uc.Reason)
74		}
75	
76		orig, ok := s.Usage[origID]
77		if !ok {
78			return fmt.Errorf("原用量标识 %q 不存在，无法更正", origID)
79		}
80		// 已撤回（含被其他更正替代，该项已在上面按重放处理）的记录不能再更正；
81		// 更正只能作用于一条仍有效的原记录。
82		if s.isWithdrawn(origID) {
83			w := s.Withdrawals[origID]
84			return fmt.Errorf("原用量 %q 已撤回（撤回原因 %q），不能更正；撤回不可恢复", origID, w.Reason)
85		}
86		origMonth := utcMonth(orig.Time)
87		if s.sealed(orig.CustomerID, origMonth) {
88			return fmt.Errorf("原用量 %q 属于客户 %s 的 %s（UTC 自然月），该月已封账，拒绝更正；账单与账后余额不变",
