94		}
95		if _, used := s.Usage[newID]; used {
96			// 标识从未使用：即使已有一条客户、时间、数量完全相同的记录，也不能
97			// 让它充当替代记录。
98			return fmt.Errorf("新用量标识 %q 已被使用，替代记录必须使用从未使用的全新标识（已有同内容记录也不能充当替代记录）", newID)
99		}
100		newCust, ok := s.Customers[newCustomerID]
101		if !ok {
102			return fmt.Errorf("新客户标识 %q 不存在", newCustomerID)
103		}
104		newMonth := t.UTC().Format("2006-01")
105		if s.sealed(newCustomerID, newMonth) {
106			return fmt.Errorf("新用量属于客户 %s 的 %s（UTC 自然月），该月已封账，拒绝更正", newCustomerID, newMonth)
107		}
108		if s.isSuspendedMonth(newCustomerID, newMonth) {
109			return fmt.Errorf("新用量属于客户 %s 的 %s（UTC 自然月），该月处于暂停区间（%s），暂停服务期间不接收用量，拒绝更正",
110				newCustomerID, newMonth, describeSuspension(s, newCustomerID, newMonth))
111		}
112		// 终止限制只约束更正替代记录的目标客户与目标 UTC 月份：目标月不早于
113		// 目标客户终止月时拒绝，原记录、替代标识及关联均不变；终止前未封账
114		// 用量仍可按原规则更正到其他客户。
115		if s.isTerminatedMonth(newCustomerID, newMonth) {
116			return fmt.Errorf("新用量属于客户 %s 的 %s（UTC 自然月），不早于该客户终止月 %s，订阅已终止不接收新用量，拒绝更正；原记录、替代标识及关联均不变",
117				newCustomerID, newMonth, s.Terminations[newCustomerID].Month)
118		}
119	
120		// 单条从零计价预检：固定单价检查 数量×单价；阶梯客户按新时间换算的
121		// UTC 月份的有效方案计价，检查分段金额不溢出。月累计溢出仍由结算把关。
122		repl := &usageRecord{ID: newID, CustomerID: newCustomerID, Time: strings.TrimSpace(newTimeText), Quantity: qty}
123		if newCust.PlanID == "" {
124			if _, err := mul64(qty, newCust.Price); err != nil {
125				return fmt.Errorf("新数量 %d × 客户 %s 单价 %d 金额溢出有符号 64 位整数范围，拒绝更正",
126					qty, newCustomerID, newCust.Price)
127			}
128		} else {
129			planID := s.effectivePlanID(newCust, newMonth)
130			if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{repl}); err != nil {
131				return fmt.Errorf("按客户 %s 的 %s 月有效方案 %q 对新数量单条从零计价失败：%v；拒绝更正",
132					newCustomerID, newMonth, planID, err)
133			}
134		}
135	
136		// 三项变更先在内存完成，再整体原子保存：原记录撤回标记、替代记录、
137		// 更正关联。原内容不改写，不占用账后操作序号。
138		now := time.Now().UTC().Format(time.RFC3339)
139		s.Withdrawals[origID] = &withdrawal{UsageID: origID, Reason: reason, CreatedAt: now}
140		s.Usage[newID] = repl
141		uc := &usageCorrection{
142			UsageID:       origID,
143			ReplacementID: newID,
144			NewCustomerID: newCustomerID,
145			NewTime:       repl.Time,
146			NewQuantity:   qty,
147			Reason:        reason,
148			CreatedAt:     now,
149		}
150		s.UsageCorrections[origID] = uc
151	
152		if err := s.save(); err != nil {
153			// 保存失败：三项全部回滚，全部业务状态不变，失败不占用新标识，
154			// 原记录不留下撤回标记或关联，可原样重试。
155			delete(s.Withdrawals, origID)
156			delete(s.Usage, newID)
157			delete(s.UsageCorrections, origID)
158			return err
159		}
160	
161		fmt.Fprintf(stdout, "已更正用量 %q：原记录按更正原因标记撤回，替代记录 %q 已登记，关联永久保存；原内容不可改写、更正不可撤销、不占用账后操作序号：\n\n",
162			origID, newID)
163		printUsageCorrection(s, uc)
164		return nil
165	}
166	
167	// predecessorCorrection 返回以指定用量为替代记录的更正（即该记录的直接
168	// 前身关联）；无前身时返回 nil。
169	func predecessorCorrection(s *state, usageID string) *usageCorrection {
170		for _, uc := range s.UsageCorrections {
171			if uc.ReplacementID == usageID {
172				return uc
173			}
174		}
175		return nil
176	}
177	
178	// successorCorrection 返回指定用量作为原记录的更正（即该记录的直接后继
179	// 关联）；无后继时返回 nil。
180	func successorCorrection(s *state, usageID string) *usageCorrection {
181		return s.UsageCorrections[usageID]
182	}
183	
184	// printUsageCorrection 输出一项用量更正：更正原因、原记录与替代记录的完整
185	// 内容、各自 UTC 月份与当前状态，以及二者的替代关联。记录状态取当前库状态：
186	// 替代记录可能已被继续更正或撤回，原记录始终保持已撤回。
187	func printUsageCorrection(s *state, uc *usageCorrection) {
188		fmt.Fprintf(stdout, "更正原因：%s\n", uc.Reason)
189		orig := s.Usage[uc.UsageID]       // 载入时已校验存在
190		repl := s.Usage[uc.ReplacementID] // 载入时已校验存在
191		fmt.Fprintln(stdout, "原记录（已按更正原因标记撤回，原内容永久保留、不可改写）：")
192		printUsageRecord(s, orig)
193		fmt.Fprintln(stdout)
194		fmt.Fprintln(stdout, "替代记录（全新标识，承载更正后的客户、时间与数量）：")
195		printUsageRecord(s, repl)
196		fmt.Fprintln(stdout)
197		fmt.Fprintf(stdout, "关联：%s（%s，UTC 月份 %s）→ %s（%s，UTC 月份 %s），原因：%s；更正不可撤销\n",
198			orig.ID, orig.CustomerID, utcMonth(orig.Time),
199			repl.ID, repl.CustomerID, utcMonth(repl.Time), uc.Reason)
200	}
201

