package main

import (
	"encoding/json"
	"os"
	"strings"
	"testing"
)

// --- 结算草案（bill draft / draft-show / draft-confirm）测试 ---

// stateBytes 读取存档原始字节，用于断言只读与重放命令不写盘。
func stateBytes(t *testing.T, h *harness) []byte {
	t.Helper()
	b, err := os.ReadFile(h.statePath())
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// loadState 在测试中直接读回 state（同包），用于检查内部状态。
func loadState(t *testing.T, h *harness) *state {
	t.Helper()
	s, err := loadStore(h.dir)
	if err != nil {
		t.Fatal(err)
	}
	return s
}

// mutateState 以通用 map 形式读入存档并按 fn 修改后写回，用于构造绕过正常
// 登记路径的损坏存档。
func mutateState(t *testing.T, h *harness, fn func(m map[string]any)) {
	t.Helper()
	data, err := os.ReadFile(h.statePath())
	if err != nil {
		t.Fatal(err)
	}
	var m map[string]any
	if err := json.Unmarshal(data, &m); err != nil {
		t.Fatal(err)
	}
	fn(m)
	out, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(h.statePath(), append(out, '\n'), 0o644); err != nil {
		t.Fatal(err)
	}
}

func fixedDraftSetup(t *testing.T) *harness {
	h := newHarness(t)
	h.mustRun("customer", "add", "acme", "月球咖啡馆", "150")
	h.writeFile("u.csv", csvHeader+
		"u-001,acme,2026-10-15T10:00:00Z,3\n"+
