	h.mustRun("bill", "draft-confirm", "da")
	err := h.runExpectErr("bill", "draft-confirm", "db")
	if !strings.Contains(err, "已由其他结算出账") || !strings.Contains(err, "不认领已有账单") {
		t.Fatalf("月份已由其他草案出账时应拒绝且不认领: %v", err)
	}
	// db 仍为待确认，且只有一张账单。
	s := loadState(t, h)
	if s.Drafts["db"].Confirmed {
		t.Fatal("被拒草案不应被确认")
	}
	if len(s.Bills) != 1 {
		t.Fatalf("被拒确认不应新增账单，账单数=%d", len(s.Bills))
	}

	// 由原结算命令先出账时同样拒绝。
	h2 := newHarness(t)
	h2.dir = h.dir
	vf := h2.writeFile("v.csv", csvHeader+"v-1,acme,2026-08-01T10:00:00Z,4\n")
	h2.mustRun("usage", "import", vf)
	h2.mustRun("bill", "draft", "dc", "acme", "2026-08")
	h2.mustRun("bill", "settle", "acme", "2026-08")
